import React, { useState, useEffect } from "react";

export default function TableEditor({ columns = [], data = [], onChange }) {

  const [tableData, setTableData] = useState([]);

  const [history, setHistory] = useState([]);
  const [future, setFuture] = useState([]);

  const [copiedRow, setCopiedRow] = useState(null);
  const [copiedColumn, setCopiedColumn] = useState(null);

  useEffect(() => {
    setTableData(data);
  }, [data]);

  // ================= UPDATE =================
  const update = (newData, newCols = columns) => {
    setTableData(newData);
    onChange(newData, newCols);
  };

  // ================= HISTORY =================
  const saveHistory = () => {
    setHistory(prev => [...prev, JSON.parse(JSON.stringify(tableData))]);
    setFuture([]);
  };

  const undo = () => {
    if (!history.length) return;

    const last = history[history.length - 1];

    setFuture(prev => [...prev, tableData]);
    setHistory(prev => prev.slice(0, -1));

    setTableData(last);
    onChange(last, columns);
  };

  const redo = () => {
    if (!future.length) return;

    const next = future[future.length - 1];

    setHistory(prev => [...prev, tableData]);
    setFuture(prev => prev.slice(0, -1));

    setTableData(next);
    onChange(next, columns);
  };

  // ================= CELL UPDATE =================
  const updateCell = (i, col, value) => {
    saveHistory();

    const updated = [...tableData];
    updated[i][col] = value;

    update(updated);
  };

  // ================= ROW OPS =================
  const insertRowAt = () => {
    const i = parseInt(prompt("Insert row index:"));
    if (isNaN(i)) return;

    saveHistory();

    const newRow = {};
    columns.forEach(c => newRow[c] = "");

    const updated = [...tableData];
    updated.splice(i, 0, newRow);

    update(updated);
  };

  const deleteRowAt = () => {
    const i = parseInt(prompt("Delete row index:"));
    if (isNaN(i)) return;

    saveHistory();

    const updated = tableData.filter((_, idx) => idx !== i);

    update(updated);
  };

  // ================= COLUMN OPS =================
  const insertColumnAt = () => {
    const name = prompt("Column name:");
    const i = parseInt(prompt("Index:"));
    if (!name || isNaN(i)) return;

    saveHistory();

    const newCols = [...columns];
    newCols.splice(i, 0, name);

    const updated = tableData.map(r => ({ ...r, [name]: "" }));

    update(updated, newCols);
  };

  const deleteColumnAt = () => {
    const name = prompt("Column name:");
    if (!name) return;

    saveHistory();

    const newCols = columns.filter(c => c !== name);

    const updated = tableData.map(r => {
      const nr = { ...r };
      delete nr[name];
      return nr;
    });

    update(updated, newCols);
  };

  // ================= COPY TABLE =================
  const copyTable = () => {
    const text =
      [columns.join("\t"),
      ...tableData.map(r => columns.map(c => r[c]).join("\t"))]
        .join("\n");

    navigator.clipboard.writeText(text);
    alert("Table Copied ✅");
  };

  const handlePaste = (e) => {
    saveHistory();

    const text = e.clipboardData.getData("text");
    const rows = text.split("\n").map(r => r.split("\t"));

    const headers = rows[0];

    const parsed = rows.slice(1).map(r => {
      const obj = {};
      headers.forEach((h, i) => obj[h] = r[i] || "");
      return obj;
    });

    update(parsed, headers);
  };

  // ================= ROW COPY =================
  const copyRow = () => {
    const i = parseInt(prompt("Row index:"));
    if (isNaN(i)) return;

    setCopiedRow({ ...tableData[i] });
  };

  const pasteRow = () => {
    if (!copiedRow) return;

    const i = parseInt(prompt("Paste index:"));
    if (isNaN(i)) return;

    saveHistory();

    const updated = [...tableData];
    updated.splice(i, 0, { ...copiedRow });

    update(updated);
  };

  // ================= COLUMN COPY =================
  const copyColumn = () => {
    const name = prompt("Column name:");
    if (!columns.includes(name)) return;

    setCopiedColumn({
      values: tableData.map(r => r[name])
    });
  };

  const pasteColumn = () => {
    if (!copiedColumn) return;

    const name = prompt("New column name:");
    const i = parseInt(prompt("Index:"));
    if (!name || isNaN(i)) return;

    saveHistory();

    const newCols = [...columns];
    newCols.splice(i, 0, name);

    const updated = tableData.map((r, idx) => ({
      ...r,
      [name]: copiedColumn.values[idx] || ""
    }));

    update(updated, newCols);
  };

  // ================= UI =================
  return (
    <div onPaste={handlePaste} tabIndex={0}>

      {/* TOOLBAR */}
      <div className="d-flex flex-wrap gap-2 mb-3">

        <button className="btn btn-secondary btn-sm" onClick={undo}>Undo</button>
        <button className="btn btn-secondary btn-sm" onClick={redo}>Redo</button>

        <button className="btn btn-primary btn-sm" onClick={insertRowAt}>Insert Row</button>
        <button className="btn btn-danger btn-sm" onClick={deleteRowAt}>Delete Row</button>

        <button className="btn btn-warning btn-sm" onClick={insertColumnAt}>Insert Column</button>
        <button className="btn btn-danger btn-sm" onClick={deleteColumnAt}>Delete Column</button>

        <button className="btn btn-outline-primary btn-sm" onClick={copyRow}>Copy Row</button>
        <button className="btn btn-outline-success btn-sm" onClick={pasteRow}>Paste Row</button>

        <button className="btn btn-outline-primary btn-sm" onClick={copyColumn}>Copy Column</button>
        <button className="btn btn-outline-success btn-sm" onClick={pasteColumn}>Paste Column</button>

        <button className="btn btn-info btn-sm" onClick={copyTable}>Copy Table</button>

      </div>

      {/* TABLE */}
      <div style={{ maxHeight: 500, overflow: "auto" }}>
        <table className="table table-bordered">

          <thead className="table-dark sticky-top">
            <tr>
              {columns.map(c => (
                <th key={c}>{c}</th>
              ))}
            </tr>
          </thead>

          <tbody>
            {tableData.map((row, i) => (
              <tr key={i}>
                {columns.map(col => (
                  <td key={col}>
                    <input
                      className="form-control form-control-sm"
                      value={
                row[col] === null || row[col] === undefined || row[col] === ""
                    ? ""
                    : !isNaN(row[col])
                    ? Number(row[col]).toFixed(3)
                    : row[col]
                }
                      onChange={(e) => updateCell(i, col, e.target.value)}
                    />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>

        </table>
      </div>

    </div>
  );
}