import React, { useState } from "react";
import axios from "axios";
import { ToastContainer, toast } from "react-toastify";

import "react-toastify/dist/ReactToastify.css";

export default function OverloadedLineLoading() {
  const [data, setData] = useState([]);
  const [snapshot, setSnapshot] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const [mode, setMode] = useState("all");

  // ================= FETCH =================
  const fetchData = async () => {
    setLoading(true);
    setData([]);
    setMessage("");

    try {
      const params = {};

      if (snapshot !== "") {
        params.snapshot = snapshot;
        setMode("snapshot");
      } else {
        setMode("all");
      }

      const res = await axios.get(
        "http://127.0.0.1:8000/network/overloaded-lines-baseline",
        { params }
      );

      if (res.status === 200) {
        const apiData = res.data.data || [];

        setData(apiData);

        setMessage(
          `Mode: ${res.data.mode || mode} | Snapshot: ${
            res.data.snapshot ?? "ALL"
          } | Overloaded Lines: ${apiData.length}`
        );

        toast.success("Loaded Successfully 🚀");
      }
    } catch (err) {
      toast.error("API Error ❌");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container" style={{ background: "#f4f6f9", minHeight: "100vh" }}>
      <div >

        {/* HEADER */}
        <div className="text-center mb-4 ">
          <h2>🔴 Overloaded Lines (75%)</h2>
          <p className="text-muted">
            Snapshot / Full Timeline Analysis
          </p>
        </div>

        {/* INPUT */}
        <div className="card shadow p-3 mb-3">
          <div className="row g-3">

            <div className="col-md-8">
              <input
                type="number"
                className="form-control form-control-lg"
                placeholder="Enter Snapshot (optional)"
                value={snapshot}
                onChange={(e) => setSnapshot(e.target.value)}
              />
              <small className="text-muted">
                Empty = All snapshots 
              </small>
            </div>

            <div className="col-md-4 d-grid">
              <button
                className="btn btn-danger btn-lg"
                onClick={fetchData}
              >
                {loading ? "Loading..." : "Get Overloaded Lines"}
              </button>
            </div>

          </div>
        </div>

        {/* STATUS */}
        <div className="text-center text-muted mb-3">
          {message || "Enter snapshot or leave empty to fetch data"}
        </div>

        {/* TABLE ONLY */}
        <div className="card shadow">
          <div style={{ maxHeight: "500px", overflowY: "auto" }}>

            {data.length > 0 ? (
              <table className="table table-hover table-bordered mb-0">
                <thead className="table-dark">
                  <tr>
                    <th>Snapshot</th>
                    <th>Line</th>
                    <th>Loading %</th>
                  </tr>
                </thead>

                <tbody>
                  {data.map((row, i) => (
                    <tr key={i}>
                      <td>{row.timestamp}</td>
                      <td>{row.line}</td>
                      <td
                        style={{
                          fontWeight: "bold",
                          color:
                            row.loading_percent > 90
                              ? "red"
                              : row.loading_percent > 75
                              ? "#ff7a00"
                              : "green",
                        }}
                      >
                        {row.loading_percent.toFixed(2)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="text-center p-5 text-muted">
                No overloaded lines found
              </div>
            )}

          </div>
        </div>

      </div>

      <ToastContainer />
    </div>
  );
}