import React, { useState, useEffect, useCallback } from "react";

function Components({ paths, registerSave }) {

  const emptyTable = { columns: [], rows: [] };

  const [table, setTable] = useState(emptyTable);

  // ============================
  // LOAD DATA (ONLY photovoltaic)
  // ============================
  useEffect(() => {
    console.log("Photovoltaic data:", paths?.photovoltaic);

    setTable(paths?.photovoltaic || emptyTable);

  }, [paths]);

  // ============================
  // UPDATE CELL
  // ============================
  const updateCell = (rowIndex, column, value) => {
    const updatedRows = [...table.rows];
    updatedRows[rowIndex][column] = value;

    setTable(prev => ({
      ...prev,
      rows: updatedRows
    }));
  };

  // ============================
  // SAVE FUNCTION
  // ============================
  const saveFn = useCallback(() => {
    return {
      photovoltaic: table.rows
    };
  }, [table]);

  // ============================
  // REGISTER SAVE
  // ============================
  useEffect(() => {
    if (registerSave) {
      registerSave(saveFn);
    }
  }, [saveFn, registerSave]);

  // ============================
  // VALUE FORMAT (IMPORTANT)
  // ============================
  const getDisplayValue = (val) => {
    if (val === 0) return 0;              // ✅ show 0
    if (val === false) return false;      // handled separately
    if (val === null || val === undefined) return "";
    return val;
  };

  // ============================
  // UI
  // ============================
  if (!table.columns || table.columns.length === 0) {
    return <p className="text-muted">No Photovoltaic Data</p>;
  }

  return (
    <div className="container mt-3">

      <h4 className="mb-3">Photovoltaic</h4>

      <div
        className="table-responsive"
        style={{ maxHeight: "400px", overflowY: "auto" }}
      >
        <table className="table table-bordered table-striped table-hover">

          {/* HEADER */}
          <thead className="table-dark" style={{ position: "sticky", top: 0 }}>
            <tr>
              {table.columns.map(col => (
                <th key={col}>{col}</th>
              ))}
            </tr>
          </thead>

          {/* BODY */}
          <tbody>
            {table.rows.map((row, i) => (
              <tr key={i}>
                {table.columns.map(col => {

                  const value = row[col];

                  return (
                    <td key={col}>
                      {typeof value === "boolean" ? (
                        <input
                          type="checkbox"
                          checked={value}
                          onChange={(e) =>
                            updateCell(i, col, e.target.checked)
                          }
                        />
                      ) : (
                        <input
                          className="form-control form-control-sm"
                          value={getDisplayValue(value)}
                          onChange={(e) => {
                            let val = e.target.value;

                            // ✅ preserve types
                            if (val === "") val = "";
                            else if (val === "true") val = true;
                            else if (val === "false") val = false;
                            else if (!isNaN(val)) val = Number(val);

                            updateCell(i, col, val);
                          }}
                        />
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>

        </table>
      </div>

    </div>
  );
}

export default Components;