import React, { useState } from "react";
import axios from "axios";
import { ToastContainer, toast } from "react-toastify";
import Sidebar from "../../Componants/Sidebar";
import "react-toastify/dist/ReactToastify.css";

export default function VoltageAngle() {
  const [data, setData] = useState([]);
  const [bus, setBus] = useState("");
  const [busList, setBusList] = useState([]);
  const [snapshot, setSnapshot] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  // ================= FETCH DATA =================
  const fetchData = async () => {
    setLoading(true);
    setMessage("");
    setData([]);
    setBus("");

    try {
      const url = "http://127.0.0.1:8000/network/voltage-angle-baseline";

      const params = {};
      if (snapshot) params.snapshot = snapshot;

      const res = await axios.get(url, { params });

      if (res.status === 200) {
        const apiData = res.data.data || res.data;

        setData(apiData);

        // ✅ Extract buses dynamically
        if (apiData.length > 0) {
          const keys = Object.keys(apiData[0]).filter(
            (k) => k !== "snapshot"
          );
          setBusList(keys);
        }

        toast.success("Voltage Angle Loaded ⚡");
        setMessage(`Loaded ${apiData.length} records`);
      }
    } catch (error) {
      setMessage("Failed to fetch data ❌");
      toast.error("API Error");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // ================= FILTERED TABLE =================
  const filteredData =
    bus && data.length > 0
      ? data.map((d) => ({
          snapshot: d.snapshot,
          [bus]: d[bus],
        }))
      : data;

  return (
    <div className="d-flex" style={{ minHeight: "100vh", background: "#f4f6f9" }}>
      

      <div className="flex-grow-1 p-4">
      <div style={{ width: "100%", maxWidth: "1300px" ,marginLeft: "250px"}}>

          {/* HEADER */}
          <div className="mb-4 text-center">
            <h2 className="fw-bold">⚡ Voltage Angle Table</h2>
            <p className="text-muted">
              Bus-wise voltage angle data
            </p>
          </div>

          {/* FILTER CARD */}
          <div className="card shadow border-0 rounded-4 p-4 mb-4">
            <div className="row g-3">

              {/* DROPDOWN */}
              <div className="col-md-5">
                <select
                  className="form-select form-select-lg"
                  value={bus}
                  onChange={(e) => setBus(e.target.value)}
                  disabled={busList.length === 0}
                >
                  <option value="">
                    {busList.length === 0
                      ? "Fetch data first"
                      : "Select Bus (optional)"}
                  </option>

                  {busList.map((b, i) => (
                    <option key={i} value={b}>
                      {b}
                    </option>
                  ))}
                </select>
              </div>

              {/* SNAPSHOT */}
              <div className="col-md-5">
                <input
                  type="number"
                  className="form-control form-control-lg"
                  placeholder="Snapshot Index (optional)"
                  value={snapshot}
                  onChange={(e) => setSnapshot(e.target.value)}
                />
              </div>

              {/* BUTTON */}
              <div className="col-md-2 d-grid">
                <button
                  className="btn btn-primary btn-lg fw-bold"
                  onClick={fetchData}
                  disabled={loading}
                >
                  {loading ? "Loading..." : "Fetch"}
                </button>
              </div>

            </div>
          </div>

          {/* STATUS */}
          <div className="text-center mb-3 text-muted">
            {message || "Click fetch to load data"}
          </div>

          {/* TABLE */}
          <div className="card shadow-lg rounded-4">

            {filteredData.length > 0 ? (
              <div
                className="table-responsive"
                style={{ maxHeight: "450px", overflowY: "auto" }}
              >
                <table className="table table-hover mb-0">

                  <thead
                    className="table-dark"
                    style={{ position: "sticky", top: 0 }}
                  >
                    <tr>
                      {Object.keys(filteredData[0]).map((key) => (
                        <th key={key}>{key}</th>
                      ))}
                    </tr>
                  </thead>

                  <tbody>
                    {filteredData.map((row, i) => (
                      <tr key={i}>
                        {Object.values(row).map((val, j) => (
                          <td key={j}>
                            {typeof val === "number"
                              ? val.toFixed(3)
                              : val}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>

                </table>
              </div>
            ) : (
              <div className="text-center p-5 text-muted">
                {loading ? "Loading..." : "No Data"}
              </div>
            )}

          </div>

        </div>
      </div>
    </div>
  );
}