import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  GeoJSON,
  Marker
} from "react-leaflet";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "bootstrap/dist/css/bootstrap.min.css";

export default function NetworkMap() {
  const [buses, setBuses] = useState(null);
  const [lines, setLines] = useState(null);
  const [lineLabels, setLineLabels] = useState([]);
  const [showMap, setShowMap] = useState(false);
  const [loading, setLoading] = useState(false);

  const mapRef = useRef(null);

  // =========================
  // FETCH DATA
  // =========================
  const fetchNetwork = async () => {
    setLoading(true);
    try {
      const res = await axios.get(
        "http://127.0.0.1:8000/network/network-map"
      );

      const parsedBuses =
        typeof res.data.buses === "string"
          ? JSON.parse(res.data.buses)
          : res.data.buses;

      const parsedLines =
        typeof res.data.lines === "string"
          ? JSON.parse(res.data.lines)
          : res.data.lines;

      setBuses(parsedBuses);
      setLines(parsedLines);
      setLineLabels(res.data.line_labels || []);
      setShowMap(true);

      // Fit bounds
      setTimeout(() => {
        if (mapRef.current && parsedBuses?.features?.length) {
          const layer = L.geoJSON(parsedBuses);
          mapRef.current.fitBounds(layer.getBounds());
        }
      }, 400);

    } catch (err) {
      console.error(err);
      alert("Failed to load network");
    }
    setLoading(false);
  };

  // =========================
  // AUTO LOAD (NO BUTTON)
  // =========================
  useEffect(() => {
    const loaded = sessionStorage.getItem("network_loaded");

    if (!loaded) {
      fetchNetwork(); // 🚀 AUTO RUN
      sessionStorage.setItem("network_loaded", "true");
    } else {
      fetchNetwork(); // optional: always refresh
    }
  }, []);

  // =========================
  // BUS STYLE
  // =========================
  const pointToLayer = (feature, latlng) => {
    return L.circleMarker(latlng, {
      radius: 5,
      fillColor: "#6c757d",
      color: "#fff",
      weight: 1,
      fillOpacity: 1
    });
  };

  // =========================
  // LINE STYLE
  // =========================
  const lineStyle = () => ({
    color: "#6c757d",
    weight: 3
  });

  return (
    <div className="container-fluid p-0">

      {/* =========================
          LOADING SCREEN
      ========================== */}
      {!showMap && (
        <div className="d-flex justify-content-center align-items-center vh-100">
          <div className="text-center">
            <div className="spinner-border text-primary mb-3"></div>
            <p className="text-muted">
              {loading ? "Loading Network Map..." : "Preparing map..."}
            </p>
          </div>
        </div>
      )}

      {/* =========================
          MAP VIEW
      ========================== */}
      {showMap && (
        <div style={{ position: "relative" }}>

          {/* TOP BAR */}
          <div className="position-absolute top-0 start-50 translate-middle-x mt-3 z-3">
            <div className="card shadow-sm px-3 py-2 d-flex flex-row align-items-center gap-3">
              
              <strong>Network Map</strong>

              <button
                onClick={fetchNetwork}
                className="btn btn-sm btn-outline-primary"
              >
                Refresh
              </button>
            </div>
          </div>

          <MapContainer
            ref={mapRef}
            center={[28.4595, 77.0266]}
            zoom={14}
            style={{ height: "100vh", width: "100%" }}
          >
            <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

            {/* LINES */}
            {lines && (
              <GeoJSON data={lines} style={lineStyle} />
            )}

            {/* BUS POINTS */}
            {buses && (
              <GeoJSON
                data={buses}
                pointToLayer={pointToLayer}
              />
            )}

            {/* BUS LABELS */}
            {buses &&
              buses.features.map((f, i) => (
                <Marker
                  key={i}
                  position={[
                    f.geometry.coordinates[1],
                    f.geometry.coordinates[0]
                  ]}
                  icon={L.divIcon({
                    html: `
                      <div style="
                        width:20px;
                        height:20px;
                        display:flex;
                        justify-content:center;
                        align-items:center;
                        font-size:10px;
                        font-weight:600;
                        color:white;
                        background:#0d6efd;
                        border-radius:50%;
                        border:2px solid #fff;
                        box-shadow:0 2px 6px rgba(0,0,0,0.3);
                      ">
                        ${f.properties.name}
                      </div>
                    `,
                    className: ""
                  })}
                />
              ))}

            {/* LINE LABELS */}
            {lineLabels.map((l, i) => (
              <Marker
                key={i}
                position={[l.lat, l.lon]}
                icon={L.divIcon({
                  html: `
                    <div style="
                      font-size:10px;
                      font-weight:600;
                      color:#0d6efd;
                      background:#fff;
                      border:1px solid #dee2e6;
                      padding:2px 6px;
                      border-radius:4px;
                    ">
                      ${l.line}
                    </div>
                  `,
                  className: ""
                })}
              />
            ))}
          </MapContainer>
        </div>
      )}
    </div>
  );
}