import React, { useEffect, useMemo } from "react";

const InternalLoadTable = ({
  data = [],
  params = {},
  options = {},
  updateParam,
  toggleSelect,
  rowStyle,
}) => {

  const columns = [
    "floor",
    "wall",
    "roof",
    "window",
    "tightness",
    "shading",
  ];

  // ================= SAFE ID =================
  const safeId = (id) =>
    id === undefined || id === null ? "" : String(id).trim();

  // ================= UNIQUE BUILDINGS =================
  const uniqueData = useMemo(() => {
    const seen = new Set();

    return (data || []).filter((b) => {
      const id = safeId(b?.name);
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
  }, [data]);

  // ============================================================
  // 🔥 AUTO SET DEFAULTS (NO USE TYPE)
  // ============================================================
  useEffect(() => {
    uniqueData.forEach((b) => {
      const id = safeId(b?.name);

      columns.forEach((key) => {
        const current = params?.[id]?.[key];
        const defaultVal = options?.[key]?.[0]?.value;

        // ✅ Fix: handle undefined, empty, or "NONE"
        if (
          current === undefined ||
          current === null ||
          current === "" ||
          current === "NONE"
        ) {
          if (defaultVal !== undefined) {
            updateParam(id, key, defaultVal);
          }
        }
      });
    });
  }, [uniqueData, options]);

  return (
    <div className="h-75 overflow-auto">
      <table className="table table-hover table-sm m-0">

        {/* HEADER */}
        <thead className="table-dark sticky-top">
          <tr>
            <th>Building</th>
            {columns.map((k) => (
              <th key={k}>{k}</th>
            ))}
          </tr>
        </thead>

        {/* BODY */}
        <tbody>
          {uniqueData.map((b, i) => {
            const id = safeId(b?.name);

            return (
              <tr
                key={id || i}
                onClick={() => toggleSelect(id)}
                style={rowStyle(id)}
              >
                <td><b>{id}</b></td>

                {columns.map((key) => {
                  const defaultVal = options?.[key]?.[0]?.value;

                  const value =
                    params?.[id]?.[key] === "NONE"
                      ? defaultVal // 🔥 FIX: override NONE
                      : params?.[id]?.[key] ?? defaultVal ?? "";

                  return (
                    <td key={`${id}-${key}`}>
                      <select
                        className="form-select form-select-sm"
                        value={value}
                        onChange={(e) => {
                          e.stopPropagation();
                          updateParam(id, key, e.target.value);
                        }}
                      >
                        {(options?.[key] || []).map((o, idx) => (
                          <option key={idx} value={o.value}>
                            {o.label}
                          </option>
                        ))}
                      </select>
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>

      </table>
    </div>
  );
};

export default InternalLoadTable;