import React, { useState } from "react";
import axios from "axios";
import TableEditor from "./BaselineTable";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { useNavigate } from "react-router-dom";
import NetworkLayout from "./NetworkLayout";

const TABS = [
  "buses",
  "generators",
  "loads",
  "transformers",
  "transformer_types",
  "lines",
  "load_p_set",
  "load_q_set",
  "snapshots",
  "generator_pmax"
];

export default function BaselineNetwork() {
  const [filterDate, setFilterDate] = useState("");
  const [activeTab, setActiveTab] = useState("buses");
  const [loading, setLoading] = useState(false);
  const [tables, setTables] = useState({});
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  // ✅ CHECK 2023 ONLY
  const isValid2023 = (date) => {
    if (!date) return false;
    return date.startsWith("2023");
  };

  // ================= FETCH =================
  const fetchBaseline = async () => {
    if (!filterDate) {
      toast.warning("Please select a date first !");
      return;
    }

    // ❌ BLOCK NON-2023
    if (!isValid2023(filterDate)) {
      toast.error("Only 2023 data is allowed ❌");
      return;
    }

    try {
      setLoading(true);

      const res = await axios.post(
        "http://127.0.0.1:8000/network/baseline-network",
        { filter_date: filterDate }
      );

      const result = res.data;

      if (result.status === "error") {
        toast.error(result.message || "No data found ❌");
        setTables({});
        setErrors({});
        return;
      }

      const parsed = {};
      TABS.forEach(tab => {
        if (result[tab]?.data) {
          parsed[tab] = result[tab];
        }
      });

      toast.success(result.message || "Loaded successfully ✅");

      setTables(parsed);
      setErrors(result.errors || {});
    } catch (err) {
      toast.error("API Failed ❌");
    } finally {
      setLoading(false);
    }
  };

  // ================= UPDATE =================
  const updateTable = (tab, updatedData, updatedColumns = null) => {
    setTables(prev => ({
      ...prev,
      [tab]: {
        ...prev[tab],
        data: updatedData,
        columns: updatedColumns || prev[tab]?.columns
      }
    }));
  };

  // ================= SAVE =================
  const saveAll = async () => {
    try {
      const payload = {};
      Object.keys(tables).forEach(tab => {
        payload[tab] = tables[tab].data;
      });

      const res = await axios.post(
        "http://127.0.0.1:8000/network/save-baseline",
        payload
      );

      const result = res.data;

      if (result.status === "success") {
        toast.success("All tables saved successfully ✅");
        setTimeout(() => navigate("/optimize"), 1500);
      } else if (result.status === "partial_success") {
        toast.warning("Some tables failed ⚠️");
      } else {
        toast.error(result.message || "Save failed ❌");
      }
    } catch (error) {
      toast.error("Network error ❌");
    }
  };

  return (
  
      <div className="baseline-wrapper">

        {/* HEADER */}
        <div className="header text-center">
          <h3>⚡ Baseline Network Input</h3>
          <p>Only 2023 dataset is supported</p>
        </div>

        {/* CARD */}
        <div className="card custom-card">

          {/* INPUT */}
          <div className="row g-3 align-items-end">
            <div className="col-md-8">
              <label className="form-label">Select Date</label>
              <input
                type="date"
                className="form-control"
                value={filterDate}
                onChange={(e) => setFilterDate(e.target.value)}
              />
              {!filterDate && (
                <small className="text-danger">Date is required ⚠</small>
              )}
            </div>

            <div className="col-md-4">
              <button
                className="btn generate-btn w-100 "
                onClick={fetchBaseline}
                disabled={loading || !filterDate}
              >
                {loading ? "Loading..." : "Generate"}
              </button>
            </div>
          </div>

          {/* EMPTY */}
          {Object.keys(tables).length === 0 && (
            <div className="empty-box">
              ⚡ Click Generate to load data
            </div>
          )}

          {/* TABS */}
          {Object.keys(tables).length > 0 && (
            <>
              <ul className="nav nav-tabs custom-tabs mt-4 mb-1 ">
                {TABS.map(tab => (
                  <li key={tab} className="nav-item">
                    <button
                      className={`nav-link ${
                        activeTab === tab ? "active" : ""
                      }`}
                      onClick={() => setActiveTab(tab)}
                    >
                      {tab}
                      {errors?.[tab] && (
                        <span className="text-danger ms-1">⚠</span>
                      )}
                    </button>
                  </li>
                ))}
              </ul>

              {/* ERROR */}
              {errors?.[activeTab] && (
                <div className="alert alert-danger mt-3">
                  {errors[activeTab]}
                </div>
              )}

              {/* TABLE */}
              {tables?.[activeTab] && (
                <TableEditor
                  tab={activeTab}
                  columns={tables[activeTab].columns}
                  data={tables[activeTab].data}
                  onChange={(data, cols) =>
                    updateTable(activeTab, data, cols)
                  }
                />
              )}

              {/* SAVE */}
              <div className="text-end mt-3">
                <button className="btn save-btn" onClick={saveAll}>
                  💾 Save All
                </button>
              </div>
            </>
          )}
        </div>

        <ToastContainer />

        {/* 🔥 STYLES */}
        <style>{`
          .baseline-wrapper {
            max-width: 1200px;
            margin: auto;
            padding: 20px;
          }

          .header h3 {
            font-weight: bold;
          }

          .header p {
            color: #6c757d;
          }

          .custom-card {
            padding: 20px;
            border-radius: 12px;
            border: none;
            box-shadow: 0 6px 18px rgba(0,0,0,0.08);
          }

          .generate-btn {
            background: linear-gradient(135deg, #0ea5e9, #2563eb);
            color: white;
            border: none;
            border-radius: 8px;
          }

          .generate-btn:hover {
            transform: scale(1.03);
          }

          .save-btn {
            background: linear-gradient(135deg, #22c55e, #16a34a);
            color: white;
            border: none;
            border-radius: 8px;
            padding: 8px 20px;
          }

          .custom-tabs .nav-link {
            color: #555;
            border: none;
          }

          .custom-tabs .nav-link.active {
            border-bottom: 3px solid #0ea5e9;
            color: #0ea5e9;
            font-weight: 600;
          }

          .empty-box {
            text-align: center;
            margin-top: 30px;
            color: #888;
          }
        `}</style>
      </div>
    
  );
}