// export const searchEAEL= api.post('/search-electricity',buildingId, date)
// SEARCH EAEL DATA
export const solarPotential = () =>
  api.post("/run-simulation", { run_type: "solar_potential" });
export const searchSimulation = async (type, filters = {}) => {
  try {
    const res = await api.post("/search-simulation", {
      type ,       // eael | hotwater | cooling | aux | total
      ...filters
    });

    return res.data;

  } catch (error) {
    console.error("API ERROR:", error.response?.data || error.message);
    return { error: "API failed" };
  }
};

// ==========================
// OPTIONAL WRAPPERS (for UI ease)
// ==========================
export const searchEAELData = (filters) =>
  searchSimulation("eael", filters);

export const searchHotwaterData = (filters) =>
  searchSimulation("hotwater", filters);

export const searchAuxData = (filters) =>
  searchSimulation("aux", filters);

export const searchCoolingData = (filters) =>
  searchSimulation("cooling", filters);

export const searchTotalData = (filters) =>
  searchSimulation("total", filters);
export const searchSolarPotential = (filters) =>
  searchSimulation("solar_potential", filters);