import React, { useState, useEffect } from "react";
import Sidebar from "../../Componants/Sidebar";
import { getMapLocator } from "../../api/api";
import MapAll from "./Map_all";
import { Link } from "react-router-dom";

const MapLocator = () => {
  const [allData, setAllData] = useState({ zone: [] });
  const [selected, setSelected] = useState([]);
  const [searchText, setSearchText] = useState("");
  const [loading, setLoading] = useState(false);

  // ================= LOAD DATA =================
  useEffect(() => {
    document.body.style.overflow = "hidden"; // 🔥 STOP PAGE SCROLL

    const cached = localStorage.getItem("mapData");

    if (cached) {
      setAllData(JSON.parse(cached));
      return;
    }

    setLoading(true);

    getMapLocator()
      .then((res) => {
        const data = res.data || {};

        const formatted = {
          ...data,
          zone: data.buildings || [],
        };

        setAllData(formatted);
        localStorage.setItem("mapData", JSON.stringify(formatted));
      })
      .catch(() => {
        console.error("Map API failed");
      })
      .finally(() => setLoading(false));

    return () => {
      document.body.style.overflow = "auto"; // cleanup
    };
  }, []);

  // ================= SELECT =================
  const toggleSelect = (id) => {
    setSelected((prev) =>
      prev.includes(id)
        ? prev.filter((b) => b !== id)
        : [...prev, id]
    );
  };

  // ================= RESET =================
  const handleReset = () => {
    if (!window.confirm("Reset map data?")) return;

    localStorage.removeItem("mapData");

    setAllData({ zone: [] });
    setSelected([]);
    setSearchText("");

    window.location.reload();
  };

  return (
    <div style={{ height: "90vh", display: "flex" }}>
      <Sidebar/>
      {/* ✅ SIDEBAR (FIXED WIDTH) */}
      <div
        style={{
          width: "80px",
          background: "#111",
          height: "100vh",
          position: "fixed",
          left: 0,
          top: 0,
          zIndex: 1000
        }}
      >
       
      </div>

      {/* ✅ MAIN CONTENT */}
      <div
        style={{
          marginLeft: "150px", // 🔥 SAME AS SIDEBAR WIDTH
          width: "calc(100% - 80px)",
          display: "flex",
          flexDirection: "column",
          height: "95vh"
        }}
      >

        {/* 🔝 TOP BAR */}
        <div
          className="d-flex justify-content-between align-items-center px-3"
          style={{
            height: "40px",
            background: "linear-gradient(135deg, #0d6efd, #0dcaf0)",
            color: "#fff",
            flexShrink: 0
          }}
        >
          <h5 className="mb-0 fw-bold">🗺️ Map Locator</h5>

          <div className="d-flex align-items-center gap-2">

            <input
              type="text"
              className="form-control form-control-sm"
              placeholder="🔍 Search..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{
                width: "220px",
                borderRadius: "20px"
              }}
            />

            <Link
              to="/database"
              className="btn btn-sm btn-light"
              style={{ borderRadius: "20px" }}
            >
              🗄️ DB
            </Link>

            <button
              className="btn btn-sm btn-danger"
              style={{ borderRadius: "20px" }}
              onClick={handleReset}
            >
              🔄 Reset
            </button>
          </div>
        </div>

        {/* 🗺️ MAP AREA (NO SCROLL) */}
        <div
          style={{
            flex: 1,
            overflow: "hidden"
          }}
        >
          {loading ? (
            <div className="d-flex justify-content-center align-items-center h-100">
              <div className="spinner-border text-primary"></div>
            </div>
          ) : (
            
            <MapAll
              allData={allData}
              selected={selected}
              toggleSelect={toggleSelect}
              searchText={searchText}
            />
          )}
        </div>

      </div>
    </div>
  );
};

export default MapLocator;