import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../Componants/Sidebar";
import { getDataMenager, getLocator, saveLocator } from "../../api/api";
import MapView from "./MapViews";
import { getDBItem, setDBItem, removeDBItem } from "./db";

// TABLES
import Zone from "./zone";
import InternalLoad from "./Internal_Load";
import Hvac from "./HvacTemp";

const Locator = () => {
  const [activeTab, setActiveTab] = useState("zone");

  const [allData, setAllData] = useState({
    zone: [],
    indoor_comfort: [],
    hvac: [],
  });

  const [selected, setSelected] = useState([]);
  const [params, setParams] = useState({});
  const [options, setOptions] = useState({});
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [searchText, setSearchText] = useState("");
  const [mapMode] = useState("normal");

  const tabs = ["zone", "internal_load", "hvac"];

  // ✅ include lat & lon
  const zoneColumns = [
    "name",
    "class",
    "sub_class",
    "use_type",
    "footprint_area",
    "floor_area",
    "height",
    "floors",
    "volume_m3",
    "wall_area",
    "roof_area",
    "window_area",
    "lat",
    "lon",
  ];

  // ================= FILTER =================
  const filteredBuildings = useMemo(() => {
    return (allData.zone || []).filter((b) =>
      (b.name || "").toLowerCase().includes(searchText.toLowerCase())
    );
  }, [allData.zone, searchText]);

  // ================= AUTO SELECT =================
  useEffect(() => {
    if (searchText) {
      setSelected(filteredBuildings.map((b) => b.name));
    }
  }, [searchText, filteredBuildings]);

  // ================= LOAD OPTIONS =================
  const normalizeOptions = (arr) =>
    (arr || []).map((o) =>
      typeof o === "object"
        ? { value: o.mass_type, label: o.description }
        : { value: o, label: o }
    );

  useEffect(() => {
    const loadOptions = async () => {
      const cached = await getDBItem("locatorOptions");

      if (cached) {
        setOptions(cached);
        return;
      }

      const res = await getLocator();
      const d = res.data || {};

      const opts = {
        floor: normalizeOptions(d.floor_types),
        wall: normalizeOptions(d.wall_types),
        roof: normalizeOptions(d.roof_types),
        window: normalizeOptions(d.window_types),
        tightness: normalizeOptions(d.tightness_types),
        shading: normalizeOptions(d.shading_types),
        hotwater_temp: normalizeOptions(d.hotwater_types),
        cooling_temp: normalizeOptions(d.cooling_types),
      };

      setOptions(opts);
      await setDBItem("locatorOptions", opts);
    };

    loadOptions();
  }, []);

  // ================= LOAD DATA =================
  useEffect(() => {
    const loadData = async () => {
      const cached = await getDBItem("locatorData");

      if (cached?.allData) {
        setAllData(cached.allData);
        setParams(cached.params);
        return;
      }

      setLoading(true);

      try {
        const res = await getDataMenager();
        const data = res.data || {};

        const fixedData = {
          zone: data.zone || [],
          indoor_comfort: [],
          hvac: [],
        };

        setAllData(fixedData);

        let init = {};

        (fixedData.zone || []).forEach((b) => {
          const id = b.name;

          init[id] = {
            ...b,
            lat: b.lat ?? "",   // ✅ ensure exists
            lon: b.lon ?? "",   // ✅ ensure exists
            floor: b.floor || "",
            wall: b.wall || "",
            roof: b.roof || "",
            window: b.window || "",
            tightness: b.tightness || "",
            shading: b.shading || "",
            hotwater_temp: b.hotwater_temp ?? "",
            cooling_temp: b.cooling_temp ?? "",
          };
        });

        setParams(init);

        await setDBItem("locatorData", {
          allData: fixedData,
          params: init,
        });
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  // ================= DEFAULT FIX =================
  useEffect(() => {
    if (!Object.keys(options).length) return;

    setParams((prev) => {
      const updated = { ...prev };

      Object.keys(updated).forEach((id) => {
        const row = updated[id] || {};
        let newRow = { ...row };

        Object.keys(options).forEach((key) => {
          const defaultValue = options?.[key]?.[0]?.value;

          if (defaultValue !== undefined) {
            newRow[key] = row[key] || defaultValue;
          }
        });

        updated[id] = newRow;
      });

      return { ...updated };
    });
  }, [options]);

  // ================= REFRESH =================
  const refreshData = async () => {
    setLoading(true);
    setMessage("Refreshing...");

    try {
      await removeDBItem("locatorData");
      await removeDBItem("locatorOptions");
      window.location.reload();
    } finally {
      setLoading(false);
    }
  };

  // ================= SELECT =================
  const toggleSelect = (id) => {
    setSelected((prev) =>
      prev.includes(id)
        ? prev.filter((b) => b !== id)
        : [...prev, id]
    );
  };

  const selectAll = () => {
    setSelected(filteredBuildings.map((b) => b.name));
  };

  const clearSelection = () => {
    setSelected([]);
  };

  const rowStyle = (id) => ({
    background: selected.includes(id) ? "#ffe0b2" : "white",
    cursor: "pointer",
  });

  // ================= UPDATE =================
  const updateParam = (building, key, value) => {
    setParams((prev) => ({
      ...prev,
      [building]: {
        ...(prev[building] || {}),
        [key]: value,
      },
    }));
  };

  // ================= SAVE =================
  const handleSave = async () => {
    try {
      const finalParams = {};

      Object.keys(params).forEach((id) => {
        const row = params[id] || {};
        let newRow = { ...row };

        Object.keys(options).forEach((key) => {
          const defaultValue = options?.[key]?.[0]?.value;

          if (defaultValue !== undefined) {
            newRow[key] = row[key] || defaultValue;
          }
        });

        // ✅ KEEP lat & lon
        const { geometry, ...cleanRow } = newRow;

        cleanRow.lat = cleanRow.lat === "" ? null : Number(cleanRow.lat);
        cleanRow.lon = cleanRow.lon === "" ? null : Number(cleanRow.lon);

        finalParams[id] = cleanRow;
      });

      const payload = {
        selected_buildings: selected,
        parameters: finalParams,
      };

      console.log("🚀 PAYLOAD:", payload);

      const res = await saveLocator(payload);
      setMessage(res.data?.status || "✅ Saved");
    } catch (err) {
      console.error(err);
      setMessage("❌ Save failed");
    }
  };

  // ================= RENDER =================
  const renderTable = () => {
    switch (activeTab) {
      case "zone":
        return (
          <Zone
            data={filteredBuildings}
            params={params}
            updateParam={updateParam}
            toggleSelect={toggleSelect}
            rowStyle={rowStyle}
          />
        );

      case "internal_load":
        return (
          <InternalLoad
            data={filteredBuildings}
            options={options}
            params={params}
            updateParam={updateParam}
            toggleSelect={toggleSelect}
            rowStyle={rowStyle}
          />
        );

      case "hvac":
        return (
          <Hvac
            data={filteredBuildings}
            params={params}
            options={options}
            updateParam={updateParam}
            toggleSelect={toggleSelect}
            rowStyle={rowStyle}
          />
        );

      default:
        return null;
    }
  };

  return (
    <div className="container-fluid vh-100 overflow-hidden">
      <div className="row h-100">
        <div className="col-lg-1">
          <Sidebar />
        </div>

        <div className="col-lg-11 d-flex flex-column h-100">

          {/* SEARCH */}
          <div className="p-2 border-bottom d-flex gap-2">
            <input
              className="form-control form-control-sm"
              placeholder="🔍 Search building..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{ maxWidth: "250px" }}
            />

            <button className="btn btn-warning btn-sm" onClick={refreshData}>
              🔄 Refresh API
            </button>
          </div>

          {/* MAP */}
          <div style={{ flex: "1 1 50%" }}>
            <MapView
              allData={{ zone: filteredBuildings }}
              selected={selected}
              toggleSelect={toggleSelect}
              params={params}
              searchText={searchText}
              mapMode={mapMode}
            />
          </div>

          {/* TABS */}
          <div className="p-2 border-bottom d-flex justify-content-between">
            <div>
              <button className="btn btn-success btn-sm me-2" onClick={selectAll}>
                Select All
              </button>
              <button className="btn btn-danger btn-sm" onClick={clearSelection}>
                Clear
              </button>
            </div>

            <div>
              {tabs.map((t) => (
                <button
                  key={t}
                  className={`btn btn-sm me-2 ${
                    activeTab === t ? "btn-primary" : "btn-outline-primary"
                  }`}
                  onClick={() => setActiveTab(t)}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {/* TABLE */}
          <div style={{ flex: "1 1 50%", overflow: "auto" }}>
            {loading ? <p className="p-3">Loading...</p> : renderTable()}
          </div>

          {/* SAVE */}
          <div className="p-2 border-top">
            <button className="btn btn-primary" onClick={handleSave}>
              Save
            </button>

            {message && <div className="alert alert-info mt-2">{message}</div>}
          </div>

        </div>
      </div>
    </div>
  );
};

export default Locator;