import React, { useState, useEffect } from "react";
import Sidebar from "../../Componants/Sidebar";
import { runPeakload } from "../../api/api";
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from "recharts";

export default function Peak() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState({});
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const project_id = localStorage.getItem("project_id");

  // 🔥 extract array safely
  const getTableData = () => {
    if (Array.isArray(result)) return result;
    if (Array.isArray(result.data)) return result.data;
    if (Array.isArray(result.results)) return result.results;
    return [];
  };

  const tableData = getTableData();

  // LOAD OLD DATA + SUCCESS MESSAGE
  useEffect(() => {
    const saved = localStorage.getItem("peakResult");
    if (saved) {
      try {
        setResult(JSON.parse(saved));
      } catch (e) {
        setResult({});
      }
    }

    const savedMsg = localStorage.getItem("peakSuccess");
    if (savedMsg) {
      setSuccess(savedMsg);
    }
  }, []);

  // RUN API
  const handleRunPeak = async () => {
    try {
      setLoading(true);
      setError("");

      const res = await runPeakload();

      if (res.status === 200) {
        setResult(res.data);

        localStorage.setItem("peakResult", JSON.stringify(res.data));

        // ✅ success message
        const msg = "Peak Load calculated successfully!";
        setSuccess(msg);
        localStorage.setItem("peakSuccess", msg);

      } else {
        setError(res.message || "Something went wrong");
      }

    } catch (err) {
      setError(err.message || "Server error");
    } finally {
      setLoading(false);
    }
  };

  // format float
  const format3 = (val) => {
    const num = parseFloat(val);
    return isNaN(num) ? val : num.toFixed(3);
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#f5f7fb" }}>

      {/* SIDEBAR */}
      <div style={{ width: "250px", flexShrink: 0 }}>
        <Sidebar />
      </div>

      {/* MAIN */}
      <div style={{ flex: 1, padding: "20px", overflowY: "auto" }}>

        {/* HEADER */}
        <div
          style={{
            background: "white",
            padding: "20px",
            borderRadius: "15px",
            boxShadow: "0 4px 15px rgba(0,0,0,0.08)",
          }}
        >
          <h2>📈 Peak Load Dashboard</h2>

          <button
            onClick={handleRunPeak}
            disabled={loading}
            style={{
              padding: "10px 20px",
              borderRadius: "10px",
              border: "none",
              background: loading ? "#999" : "#ff9800",
              color: "white",
              cursor: "pointer",
              marginTop: "10px",
            }}
          >
            {loading ? "Running..." : "Run Peak Load"}
          </button>

          {/* ERROR */}
          {error && (
            <p style={{ color: "red", marginTop: "10px" }}>{error}</p>
          )}

          {/* SUCCESS */}
          {success && (
            <div
              style={{
                marginTop: "10px",
                padding: "10px",
                borderRadius: "10px",
                background: "#e8fff0",
                color: "#1b7f3a",
                fontWeight: "500",
              }}
            >
              ✅ {success}
            </div>
          )}
        </div>

        {/* CHART */}
        <div
          style={{
            background: "white",
            marginTop: "20px",
            padding: "20px",
            borderRadius: "15px",
            boxShadow: "0 4px 15px rgba(0,0,0,0.08)",
          }}
        >
          <h3>📊 Peak Load Chart</h3>

          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={tableData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="Building" />
              <YAxis />
              <Tooltip />
              <Bar
                dataKey="Peak_Load_kW"
                fill="#4f46e5"
                radius={[10, 10, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* TABLE */}
        <div
          style={{
            marginTop: "20px",
            background: "white",
            padding: "15px",
            borderRadius: "15px",
            boxShadow: "0 4px 15px rgba(0,0,0,0.08)",
            maxHeight: "400px",
            overflowY: "auto",
          }}
        >
          <h3>📋 Data Table</h3>

          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: "#111", color: "white" }}>
                <th style={{ padding: "10px" }}>Building</th>
                <th>Peak Load (kW)</th>
                <th>Peak Time</th>
              </tr>
            </thead>

            <tbody>
              {tableData.map((row, i) => (
                <tr
                  key={i}
                  style={{
                    borderBottom: "1px solid #eee",
                    textAlign: "center",
                  }}
                >
                  <td style={{ padding: "10px" }}>{row.Building}</td>
                  <td>{format3(row.Peak_Load_kW)}</td>
                  <td>{row.Peak_Time}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
}