import React, { useState, useMemo, useEffect } from "react";
import {
  LineChart, Line, XAxis, YAxis, Tooltip,
  Legend, CartesianGrid, ResponsiveContainer
} from "recharts";

import Sidebar from "../../Componants/Sidebar";
import { runTotal, searchTotalData } from "../../api/api";

import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

export default function TotalLoad() {

  const [loading, setLoading] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);

  const [error, setError] = useState("");
  const [infoMessage, setInfoMessage] = useState("");

  const [searchResult, setSearchResult] = useState([]);

  const [visibleKeys, setVisibleKeys] = useState({
    TOTAL: true,
    COOLING: true,
    DHW: true,
    EA: true,
    EL: true
  });

  const [filters, setFilters] = useState({
    building_name: "",
    start_date: "",
    end_date: "",
  });

  const [runMessage, setRunMessage] = useState("");

  useEffect(() => {
    const saved = localStorage.getItem("totalRunMessage");
    if (saved) setRunMessage(saved);
  }, []);

  // ================= VALIDATION =================
  const validate = () => {
    if (!filters.building_name.trim()) {
      const msg = "⚠️ Building name required";
      toast.warning(msg);
      setError(msg);
      return false;
    }

    if (!filters.start_date || !filters.end_date) {
      const msg = "⚠️ Start & End date required";
      toast.warning(msg);
      setError(msg);
      return false;
    }

    const start = new Date(filters.start_date);
    const end = new Date(filters.end_date);

    if (start > end) {
      const msg = "⚠️ Start date > End date";
      toast.error(msg);
      setError(msg);
      return false;
    }

    return true;
  };

  // ================= RUN =================
  const handleRunTotal = async () => {
    try {
      setLoading(true);

      const res = await runTotal();
      const msg = res?.message || "📊 Total executed";

      toast.success(msg);
      setRunMessage(msg);
      localStorage.setItem("totalRunMessage", msg);

    } catch (err) {
      const msg = err?.response?.data?.error || "Run failed";
      toast.error(msg);
      setRunMessage(msg);
    } finally {
      setLoading(false);
    }
  };

  // ================= SEARCH =================
  const handleSearch = async (e) => {
    e.preventDefault();

    if (!validate()) return;

    try {
      setSearchLoading(true);
      setError("");
      setInfoMessage("");
      setSearchResult([]);

      const res = await searchTotalData(filters);

      if (res?.error) {
        setError(res.error);
        toast.error(res.error);
        return;
      }

      const data = res?.data || [];

      if (!data.length) {
        const msg = "⚠️ No data found";
        setError(msg);
        toast.warning(msg);
        return;
      }

      const msg = `✅ ${data.length} records found`;
      setInfoMessage(msg);
      toast.success(msg);

      setSearchResult(data);

    } catch (err) {
      const msg = err?.response?.data?.error || "Search failed";
      setError(msg);
      toast.error(msg);
    } finally {
      setSearchLoading(false);
    }
  };

  // ================= FORMAT =================
  const formattedData = useMemo(() => {
    return searchResult.map((row) => {
      const d = new Date(row.timestamps || row.timestamp);

      const formatted = isNaN(d)
        ? row.timestamps
        : `${d.toLocaleDateString("en-GB")} ${String(d.getHours()).padStart(2, "0")}:00`;

      return {
        timestamp: formatted,
        TOTAL: Number(row.TOTAL_LOAD_kW || row.total_kW || 0),
        COOLING: Number(row.cooling_kW || 0),
        DHW: Number(row.dhw_kW || 0),
        EA: Number(row.ea_kW || 0),
        EL: Number(row.el_kW || 0),
      };
    });
  }, [searchResult]);

  // ================= SUMMARY (UPDATED) =================
  const summary = useMemo(() => {
    let total = 0, cooling = 0, dhw = 0, ea = 0, el = 0;

    formattedData.forEach(d => {
      total += d.TOTAL;
      cooling += d.COOLING;
      dhw += d.DHW;
      ea += d.EA;
      el += d.EL;
    });

    const count = formattedData.length || 1;

    return {
      total: total.toFixed(3),
      cooling: cooling.toFixed(3),
      dhw: dhw.toFixed(3),
      ea: ea.toFixed(3),
      el: el.toFixed(3),
      avg_total: (total / count).toFixed(3),
      hours: formattedData.length
    };
  }, [formattedData]);

  // ================= LEGEND =================
  const handleLegendClick = (e) => {
    const key = e.dataKey;

    setVisibleKeys((prev) => {
      const allVisible = Object.values(prev).every(v => v === true);

      if (allVisible) {
        return {
          TOTAL: key === "TOTAL",
          COOLING: key === "COOLING",
          DHW: key === "DHW",
          EA: key === "EA",
          EL: key === "EL"
        };
      }

      return {
        TOTAL: true,
        COOLING: true,
        DHW: true,
        EA: true,
        EL: true
      };
    });
  };

  return (
    <div className="container py-4">
      <Sidebar />
      <ToastContainer position="top-right" autoClose={3000} />

      <h2 className="text-center fw-bold">📊 Total Load Dashboard</h2>

      {/* RUN */}
      <div className="d-flex justify-content-center mb-3">
        <button onClick={handleRunTotal} className="btn btn-warning px-4 fw-bold">
          {loading ? "Running..." : "Run Total"}
        </button>
      </div>

      {/* RUN MESSAGE */}
      {runMessage && (
        <div className="d-flex justify-content-center mb-3">
          <div className="alert alert-info text-center shadow-sm" style={{ maxWidth: "700px" }}>
            {runMessage}
          </div>
        </div>
      )}

      {/* SEARCH FORM */}
      <div className="d-flex justify-content-center mb-4">
        <div className="card shadow-sm p-4" style={{ maxWidth: "700px", width: "100%" }}>
          <form onSubmit={handleSearch}>
            <h5 className="text-center fw-bold mb-3">🔍 Search Total Load</h5>

            <input
              className="form-control mb-3"
              placeholder="🏢 Building Name"
              value={filters.building_name}
              onChange={(e) => setFilters({ ...filters, building_name: e.target.value })}
            />

            <div className="row mb-3">
              <div className="col">
                <input type="date" className="form-control"
                  onChange={(e) => setFilters({ ...filters, start_date: e.target.value })}
                />
              </div>
              <div className="col">
                <input type="date" className="form-control"
                  onChange={(e) => setFilters({ ...filters, end_date: e.target.value })}
                />
              </div>
            </div>

            <button className="btn btn-primary w-100">
              {searchLoading ? "Searching..." : "Search"}
            </button>
          </form>
        </div>
      </div>

      {/* MESSAGE */}
      {infoMessage && <div className="alert alert-success text-center">{infoMessage}</div>}
      {error && <div className="alert alert-danger text-center">{error}</div>}

      {/* SUMMARY CARDS */}
      {formattedData.length > 0 && (
        <div className="row text-center mt-3">

          <div className="col-md-2"><div className="card p-2 shadow-sm"><h6>Total</h6><b>{summary.total}</b></div></div>
          <div className="col-md-2"><div className="card p-2 shadow-sm"><h6>Cooling</h6><b>{summary.cooling}</b></div></div>
          <div className="col-md-2"><div className="card p-2 shadow-sm"><h6>DHW</h6><b>{summary.dhw}</b></div></div>
          <div className="col-md-2"><div className="card p-2 shadow-sm"><h6>EA</h6><b>{summary.ea}</b></div></div>
          <div className="col-md-2"><div className="card p-2 shadow-sm"><h6>EL</h6><b>{summary.el}</b></div></div>
          <div className="col-md-2"><div className="card p-2 shadow-sm bg-light"><h6>Hours</h6><b>{summary.hours}</b></div></div>

        </div>
      )}

      {/* CHART */}
      {formattedData.length > 0 && (
        <div className="mt-4 bg-white p-3 shadow-sm">
          <ResponsiveContainer width="100%" height={400}>
            <LineChart data={formattedData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" />
              <YAxis />
              <Tooltip />
              <Legend onClick={handleLegendClick} />

              {visibleKeys.TOTAL && <Line dataKey="TOTAL" stroke="#ff5733" strokeWidth={3} />}
              {visibleKeys.COOLING && <Line dataKey="COOLING" stroke="#007bff" />}
              {visibleKeys.DHW && <Line dataKey="DHW" stroke="#28a745" />}
              {visibleKeys.EA && <Line dataKey="EA" stroke="#ffc107" />}
              {visibleKeys.EL && <Line dataKey="EL" stroke="#6f42c1" />}
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* TABLE */}
      {formattedData.length > 0 && (
        <div className="mt-4 table-responsive" style={{ maxHeight: "350px", overflowY: "auto" }}>
          <table className="table table-bordered">
            <thead className="table-dark">
              <tr>
                <th>Time</th>
                <th>Total</th>
                <th>Cooling</th>
                <th>DHW</th>
                <th>EA</th>
                <th>EL</th>
              </tr>
            </thead>
            <tbody>
              {formattedData.map((row, i) => (
                <tr key={i}>
                  <td>{row.timestamp}</td>
                  <td>{row.TOTAL.toFixed(3)}</td>
                  <td>{row.COOLING.toFixed(3)}</td>
                  <td>{row.DHW.toFixed(3)}</td>
                  <td>{row.EA.toFixed(3)}</td>
                  <td>{row.EL.toFixed(3)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

    </div>
  );
}