import React, { useState } from "react";
import axios from "axios";
import { ToastContainer, toast } from "react-toastify";
import Sidebar from "../../Componants/Sidebar";
import "react-toastify/dist/ReactToastify.css";

export default function RealPower() {
  const [data, setData] = useState([]);
  const [line, setLine] = useState("");
  const [lineList, setLineList] = useState([]);
  const [snapshot, setSnapshot] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const fetchData = async () => {
    setLoading(true);
    setMessage("");
    setData([]);

    try {
      let url = "http://127.0.0.1:8000/network/real-power-baseline";

      const params = {};
      if (snapshot) params.snapshot = snapshot;

      const res = await axios.get(url, { params });

      if (res.status === 200) {
        const apiData = res.data.data;

        setData(apiData);

        // ✅ Extract line names dynamically
        if (apiData.length > 0) {
          const keys = Object.keys(apiData[0]).filter(
            (k) => k !== "snapshot"
          );
          setLineList(keys);
        }

        toast.success(res.data.message);
        setMessage(`Loaded ${apiData.length} records`);
      }
    } catch (error) {
      setMessage("Failed to fetch data ❌");
      toast.error("API Error");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Filter data based on selected line
  const filteredData =
    line && data.length > 0
      ? data.map((d) => ({
          snapshot: d.snapshot,
          [line]: d[line],
        }))
      : data;

  return (
    <div className="d-flex" style={{ minHeight: "100vh", background: "#f4f6f9" }}>
   

      {/* MAIN CONTENT */}
      <div className="flex-grow-1 p-4 d-flex justify-content-center">

        <div style={{ width: "100%", maxWidth: "1300px" }}>

          {/* HEADER */}
          <div className="mb-4 text-center">
            <h2 className="fw-bold">⚡ Real Power Flow</h2>
            <p className="text-muted">Interactive time-series data viewer</p>
          </div>

          {/* FILTER CARD */}
          <div className="container-fluid card border-0 shadow-sm rounded-4 p-4 mb-4 bg-white">
            <div className="row g-3 align-items-center">

              {/* 🔽 DROPDOWN */}
              <div className="col-md-5">
                <select
                  className="form-select form-select-lg"
                  value={line}
                  onChange={(e) => setLine(e.target.value)}
                  disabled={lineList.length === 0}
                >
                  <option value="">
                    {lineList.length === 0
                      ? "Fetch data first"
                      : "Select Line (optional)"}
                  </option>

                  {lineList.map((l, i) => (
                    <option key={i} value={l}>
                      {l}
                    </option>
                  ))}
                </select>
              </div>

              {/* SNAPSHOT */}
              <div className="col-md-5">
                <input
                  type="number"
                  className="form-control form-control-lg"
                  placeholder="Snapshot Index (optional)"
                  value={snapshot}
                  onChange={(e) => setSnapshot(e.target.value)}
                />
              </div>

              {/* BUTTON */}
              <div className="col-md-2 d-grid">
                <button
                  className="btn btn-primary btn-lg fw-bold"
                  onClick={fetchData}
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2"></span>
                      Loading...
                    </>
                  ) : (
                    "Fetch"
                  )}
                </button>
              </div>

            </div>
          </div>

          {/* STATUS */}
          <div className="text-center mb-3">
            <h6 className="text-secondary">
              {message || "Enter filters and fetch data"}
            </h6>
          </div>

          {/* TABLE CARD */}
          <div className="card border-0 shadow-lg rounded-4">

            {filteredData.length > 0 ? (
              <div
                className="table-responsive"
                style={{
                  maxHeight: "450px",
                  overflowY: "auto"
                }}
              >
                <table className="table table-hover mb-0 align-middle">

                  <thead
                    className="table-dark"
                    style={{
                      position: "sticky",
                      top: 0,
                      zIndex: 2
                    }}
                  >
                    <tr>
                      {Object.keys(filteredData[0]).map((key) => (
                        <th key={key}>{key}</th>
                      ))}
                    </tr>
                  </thead>

                  <tbody>
                    {filteredData.map((row, index) => (
                      <tr key={index}>
                        {Object.values(row).map((val, i) => (
                          <td key={i}>
                            {typeof val === "number"
                              ? val.toFixed(2)
                              : val}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>

                </table>
              </div>
            ) : (
              <div className="text-center p-5 text-muted">
                {loading ? "Loading data..." : "No data available"}
              </div>
            )}

          </div>

        </div>
      </div>
    </div>
  );
}