import React, { useState, useEffect } from "react";
import axios from "axios";
import Sidebar from "../../Componants/Sidebar";
import NetworkLayout from "./NetworkLayout";

export default function BaselinePowerflowNetwork() {
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");
  const [statusType, setStatusType] = useState("idle");
  const [isOptimized, setIsOptimized] = useState(false);

  // ✅ Load saved state on page load
  useEffect(() => {
    const saved = localStorage.getItem("baseline_optimized");
    if (saved === "true") {
      setIsOptimized(true);
      setStatusMsg("Already Optimized ✅");
      setStatusType("success");
    }
  }, []);

  const runOptimization = async () => {
    if (isOptimized) return; // 🚫 Prevent re-run

    setLoading(true);
    setProgress(10);
    setStatusMsg("Initializing optimization...");
    setStatusType("running");

    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 90) return prev;
        return prev + 8;
      });
    }, 400);

    try {
      const res = await axios.get(
        "http://127.0.0.1:8000/network/optimize-baseline-network"
      );

      clearInterval(interval);

      setProgress(100);
      setStatusMsg("Finalizing results...");
      setStatusType("running");

      setTimeout(() => {
        setProgress(null);

        // ✅ SAVE STATE
        localStorage.setItem("baseline_optimized", "true");

        setIsOptimized(true);
        setStatusMsg(
          res.data.message || "Optimization Completed Successfully 🎉"
        );
        setStatusType("success");
      }, 800);

    } catch (error) {
      clearInterval(interval);
      setProgress(null);
      setStatusMsg("Optimization Failed ❌");
      setStatusType("error");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // 🔁 Optional reset (for testing)
  const resetOptimization = () => {
    localStorage.removeItem("baseline_optimized");
    setIsOptimized(false);
    setStatusMsg(" Ready to run.");
    setStatusType("idle");
  };

  const getStatusColor = () => {
    switch (statusType) {
      case "success":
        return "bg-success-subtle text-success";
      case "error":
        return "bg-danger-subtle text-danger";
      case "running":
        return "bg-info-subtle text-info";
      default:
        return "bg-light text-muted";
    }
  };

  return (
    
    <div className="d-flex" style={{ minHeight: "50vh" }}>
     

      <div className="container d-flex justify-content-center">
        <div
          className="card border-0 shadow-lg p-4 mt-5"
          style={{
            width: "100%",
            maxWidth: "600px",
            borderRadius: "20px",
            background: "hsla(57, 66%, 55%, 0.85)",
          }}
        >
          <div className="text-center mb-4">
            <h2 className="fw-bold">⚡ Power Network Optimization</h2>
            <p className="text-muted mb-0">
              Run baseline PyPSA optimization ,2023 data is availble ... please enter 2023
            </p>
          </div>

          {/* STATUS */}
          <div className="text-center mb-4">
            <span className={`badge px-3 py-2 ${getStatusColor()}`}>
              {statusMsg || "Ready to Run"}
            </span>
          </div>

          {/* PROGRESS */}
          {progress !== null && (
            <div className="mb-4">
              <div className="progress" style={{ height: "18px" }}>
                <div
                  className="progress-bar progress-bar-striped progress-bar-animated"
                  style={{ width: `${progress}%` }}
                >
                  {progress}%
                </div>
              </div>
            </div>
          )}

          {/* BUTTON */}
          <div className="text-center">
            <button
              className="btn fw-bold px-5 py-2"
              onClick={runOptimization}
              disabled={loading || isOptimized} // ✅ disable permanently
              style={{
                borderRadius: "30px",
                background: isOptimized
                  ? "#28a745"
                  : loading
                  ? "#ccc"
                  : "linear-gradient(90deg, #00c6ff, #0072ff)",
                color: "#fff",
                border: "none",
              }}
            >
              {isOptimized
                ? "✅ Already Optimized"
                : loading
                ? "Optimizing..."
                : "🚀 Run Optimization"}
            </button>
          </div>

          {/* 🔁 RESET BUTTON (optional) */}
          <div className="text-center mt-3">
            <button
              className="btn btn-sm btn-outline-dark"
              onClick={resetOptimization}
            >
              Re-optimize
            </button>
          </div>
        </div>
      </div>
       
    </div>

  );
}