import React, { useState, useEffect, useCallback } from "react";

function Assemblies({ paths, type, registerSave }) {

  const emptyTable = { columns: [], rows: [] };

  const [activeTab, setActiveTab] = useState("floor");

  const [allData, setAllData] = useState({
    floor: emptyTable,
    wall: emptyTable,
    roof: emptyTable,
    shading: emptyTable,
    tightness: emptyTable,
    window: emptyTable,
    mass: emptyTable,

    hvac_controller: emptyTable,
    hvac_cooling: emptyTable,
    hvac_heating: emptyTable,
    hvac_hotwater: emptyTable,
    hvac_ventilation: emptyTable,

    supply_cooling: emptyTable,
    supply_electricity: emptyTable,
    supply_heating: emptyTable,
    supply_hotwater: emptyTable
  });

  // ============================
  // DEFAULT TAB
  // ============================
  useEffect(() => {
    if (type === "hvac") setActiveTab("hvac_controller");
    if (type === "envelope") setActiveTab("floor");
    if (type === "supply") setActiveTab("supply_cooling");
  }, [type]);

  // ============================
  // LOAD DATA
  // ============================
  useEffect(() => {
    setAllData({
      floor: paths?.floor || emptyTable,
      wall: paths?.wall || emptyTable,
      roof: paths?.roof || emptyTable,
      shading: paths?.shading || emptyTable,
      tightness: paths?.tightness || emptyTable,
      window: paths?.window || emptyTable,
      mass: paths?.mass || emptyTable,

      hvac_controller: paths?.hvac_controller || emptyTable,
      hvac_cooling: paths?.hvac_cooling || emptyTable,
      hvac_heating: paths?.hvac_heating || emptyTable,
      hvac_hotwater: paths?.hvac_hotwater || emptyTable,
      hvac_ventilation: paths?.hvac_ventilation || emptyTable,

      supply_cooling: paths?.supply_cooling || emptyTable,
      supply_electricity: paths?.supply_electricity || emptyTable,
      supply_heating: paths?.supply_heating || emptyTable,
      supply_hotwater: paths?.supply_hotwater || emptyTable
    });
  }, [paths]);

  // ============================
  // UPDATE CELL
  // ============================
  const updateCell = (tab, rowIndex, column, value) => {
    const updatedRows = [...allData[tab].rows];
    updatedRows[rowIndex][column] = value;

    setAllData(prev => ({
      ...prev,
      [tab]: {
        ...prev[tab],
        rows: updatedRows
      }
    }));
  };

  // ============================
  // SAVE FUNCTION
  // ============================
  const saveFn = useCallback(() => {
    return {
      type: type,

      floor: allData.floor.rows,
      wall: allData.wall.rows,
      roof: allData.roof.rows,
      shading: allData.shading.rows,
      tightness: allData.tightness.rows,
      window: allData.window.rows,
      mass: allData.mass.rows,

      hvac_controller: allData.hvac_controller.rows,
      hvac_cooling: allData.hvac_cooling.rows,
      hvac_heating: allData.hvac_heating.rows,
      hvac_hotwater: allData.hvac_hotwater.rows,
      hvac_ventilation: allData.hvac_ventilation.rows,

      supply_cooling: allData.supply_cooling.rows,
      supply_electricity: allData.supply_electricity.rows,
      supply_heating: allData.supply_heating.rows,
      supply_hotwater: allData.supply_hotwater.rows,

      hvac_folder: paths?.hvac_dir || "",
      supply_folder: paths?.supply_dir || ""
    };
  }, [allData, paths, type]);

  useEffect(() => {
    if (registerSave) registerSave(saveFn);
  }, [saveFn, registerSave]);

  // ============================
  // TABLE
  // ============================
  const renderTable = (tab) => {
    const table = allData[tab];

    if (!table || !table.columns || table.columns.length === 0) {
      return (
        <div className="alert alert-info text-center">
          No {tab} data available
        </div>
      );
    }

    return (
      <div className="card shadow-sm">
        <div className="card-body p-0">
          <div className="table-responsive" style={{ maxHeight: "400px" }}>
            <table className="table table-hover table-bordered mb-0">

              <thead className="table-primary" style={{ position: "sticky", top: 0 }}>
                <tr>
                  {table.columns.map(col => (
                    <th key={col} className="text-nowrap">{col}</th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {table.rows.map((row, i) => (
                  <tr key={i}>
                    {table.columns.map(col => (
                      <td key={col}>
                        {typeof row[col] === "boolean" ? (
                          <div className="form-check text-center">
                            <input
                              type="checkbox"
                              className="form-check-input"
                              checked={row[col]}
                              onChange={(e) =>
                                updateCell(tab, i, col, e.target.checked)
                              }
                            />
                          </div>
                        ) : (
                          <input
                            className="form-control form-control-sm"
                            value={row[col] ?? ""}
                            
                            // ✅ FIX: allow typing freely
                            onChange={(e) => {
                              updateCell(tab, i, col, e.target.value);
                            }}

                            // ✅ Convert only when user leaves input
                            onBlur={(e) => {
                              let val = e.target.value;

                              if (val === "true") val = true;
                              else if (val === "false") val = false;
                              else if (val !== "" && !isNaN(val)) val = Number(val);

                              updateCell(tab, i, col, val);
                            }}
                          />
                        )}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>

            </table>
          </div>
        </div>
      </div>
    );
  };

  // ============================
  // TABS
  // ============================
  const renderTabs = (tabs, titleFormatter) => (
    <>
      <ul className="nav nav-pills mb-3 flex-wrap gap-2">
        {tabs.map(tab => (
          <li className="nav-item" key={tab}>
            <button
              className={`btn ${activeTab === tab ? "btn-primary" : "btn-outline-primary"}`}
              onClick={() => setActiveTab(tab)}
            >
              {titleFormatter(tab)}
            </button>
          </li>
        ))}
      </ul>

      {renderTable(activeTab)}
    </>
  );

  // ============================
  // ENVELOPE
  // ============================
  if (type === "envelope") {
    const tabs = ["floor", "wall", "roof", "shading", "tightness", "window", "mass"];

    return (
      <div className="container-fluid mt-3">
        <div className="card shadow">
          <div className="card-header bg-dark text-white">
            <h5 className="mb-0">Envelope Assemblies</h5>
          </div>
          <div className="card-body">
            {renderTabs(tabs, (tab) => tab.toUpperCase())}
          </div>
        </div>
      </div>
    );
  }

  // ============================
  // HVAC
  // ============================
  if (type === "hvac") {
    const tabs = [
      "hvac_controller",
      "hvac_cooling",
      "hvac_heating",
      "hvac_hotwater",
      "hvac_ventilation"
    ];

    return (
      <div className="container-fluid mt-3">
        <div className="card shadow">
          <div className="card-header bg-success text-white">
            <h5 className="mb-0">HVAC Systems</h5>
          </div>
          <div className="card-body">
            {renderTabs(tabs, (tab) => tab.replace("hvac_", "").toUpperCase())}
          </div>
        </div>
      </div>
    );
  }

  // ============================
  // SUPPLY
  // ============================
  if (type === "supply") {
    const tabs = [
      "supply_cooling",
      "supply_electricity",
      "supply_heating",
      "supply_hotwater"
    ];

    return (
      <div className="container-fluid mt-3">
        <div className="card shadow">
          <div className="card-header bg-info text-white">
            <h5 className="mb-0">Supply Systems</h5>
          </div>
          <div className="card-body">
            {renderTabs(tabs, (tab) =>
              tab.replace("supply_", "").replace("_", " ").toUpperCase()
            )}
          </div>
        </div>
      </div>
    );
  }

  return null;
}

export default Assemblies;