import React, { createContext, useContext, useState } from "react";

const LocatorContext = createContext();

export const LocatorProvider = ({ children }) => {
  const [locatorData, setLocatorData] = useState(null);
  const [locatorOptions, setLocatorOptions] = useState(null);

  return (
    <LocatorContext.Provider
      value={{
        locatorData,
        setLocatorData,
        locatorOptions,
        setLocatorOptions,
      }}
    >
      {children}
    </LocatorContext.Provider>
  );
};

export const useLocator = () => useContext(LocatorContext);