import React from "react";
import { Link } from "react-router-dom";
import Sidebar from "../../Componants/Sidebar";
import {
  FaSnowflake,
  FaShower,
  FaBolt,
  FaTools,
  FaChartBar,
  FaChartLine,
} from "react-icons/fa";

export default function Results() {
  const results = [
    {
      title: "show Cooling Demand result",
      path: "/energy-demand/cooling",
      icon: <FaSnowflake />,
      gradient: "linear-gradient(135deg, #36d1dc, #5b86e5)",
    },
    {
      title: " Show Hot Water Demand result",
      path: "/energy-demand/hotwater",
      icon: <FaShower />,
      gradient: "linear-gradient(135deg, #ff9966, #ff5e62)",
    },
    {
      title: "Show EA & EL Demand result",
      path: "/energy-demand/eael",
      icon: <FaBolt />,
      gradient: "linear-gradient(135deg, #f7971e, #ffd200)",
    },
    {
      title: "Show Aux demand result",
      path: "/energy-demand/aux",
      icon: <FaTools />,
      gradient: "linear-gradient(135deg, #757f9a, #d7dde8)",
    },
    {
      title: "Show Total Demand result",
      path: "/energy-demand/total",
      icon: <FaChartBar />,
      gradient: "linear-gradient(135deg, #11998e, #38ef7d)",
    },
    {
      title: "Peak",
      path: "/energy-demand/peak",
      icon: <FaChartLine />,
      gradient: "linear-gradient(135deg, #8e2de2, #ff6a00)",
    },
  ];

  return (
    <div>
      <Sidebar />

      <div
        style={{
          marginLeft: "150px",
          padding: "30px",
       
          minHeight: "100vh",
        }}
        className="text-center"
      >
        {/* Header */}
        <h2 style={{ fontWeight: "700", marginBottom: "5px" }}>
          📊 Energy Results 
        </h2>
        <p style={{ color: "#6b7280", marginBottom: "25px" }}>
          Explore all energy demand results click to go ..
        </p>

        {/* 3 per row grid */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)", // 🔥 FIXED 3 PER ROW
            gap: "25px",
          }}
        >
          {results.map((item, i) => (
            <Link key={i} to={item.path} style={{ textDecoration: "none" }}>
              
              <div
                style={{
                  background: item.gradient,
                  color: "white",
                  padding: "28px",
                  borderRadius: "18px",
                  backdropFilter: "blur(10px)",
                  boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
                  transition: "all 0.3s ease",
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = "translateY(-8px) scale(1.02)";
                  e.currentTarget.style.boxShadow =
                    "0 20px 40px rgba(0,0,0,0.3)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = "translateY(0) scale(1)";
                  e.currentTarget.style.boxShadow =
                    "0 10px 30px rgba(0,0,0,0.2)";
                }}
              >
                {/* Icon */}
                <div style={{ fontSize: "32px", marginBottom: "15px" }}>
                  {item.icon}
                </div>

                {/* Title */}
                <h5 style={{ fontWeight: "600" }}>{item.title}</h5>

                {/* Subtitle */}
                <p style={{ fontSize: "13px", opacity: 0.85 }}>
                  View detailed results →
                </p>
              </div>

            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}