import React from "react";
import "./Home.css";
import logo from "../images/logo.png";
import bg from "../images/g1.jpg";
import { useNavigate } from "react-router-dom";
import Navbar from "../Componants/navbar";

export default function Home() {
  const navigate = useNavigate();

  return (
    <div >
      <Navbar/>
   
    <div
   
      className="tool-container center-layout"
      style={{ backgroundImage: `url(${bg})` }}
    > 

      {/* DARK OVERLAY */}
      <div className="bg-overlay"></div>

      {/* TOP BAR */}
      <div className="topbar">
        <span>SPIBEAT Energy Platform</span>
        <div className="top-actions">
          <span>v1.0</span>
          <span className="dot"></span>
          <span>Ready</span>
        </div>
      </div>

      {/* CENTER CARD */}
      <div className="center-card glass">

        <div className="brand-center">
          <img src={logo} alt="logo" />
          <h1>SPIBEAT</h1>
          <p>Engineering Simulation Tool</p>
        </div>

        <h2 className="title">Building to grid - integrated platform </h2>

        <p className="subtitle">
          Demand • Solar Potential • PyPSA Optimization
        </p>

        <div className="actions-center">
          <button className="primary" onClick={() => navigate("/Dashboard")}>
            ▶ start
          </button>
          
        </div>


        <p className="footer-text">
          © 2026 SPIBEAT Energy Systems
        </p>

      </div>

    </div>
     </div>
  );
}