import { Link, useLocation } from "react-router-dom";
import { useState } from "react";
import "./Sidebar.css";

function NetworkBar() {
  const location = useLocation();

  const [openMenu, setOpenMenu] = useState("");
  const [openSubMenu, setOpenSubMenu] = useState("");

  const isActive = (path) => location.pathname === path;

  return (
    <div className="sidebar-container">
      <div className="sidebar-header">⚡ SPIBEAT</div>

      <nav className="sidebar-nav">

        {/* ================= HOME ================= */}
        <Link to="/" className={isActive("/") ? "active" : ""}>
          🏠 Home
        </Link>

        {/* ================= DASHBOARD ================= */}
        <Link to="/Dashboard" className={isActive("/Dashboard") ? "active" : ""}>
          📊 Dashboard
        </Link>

        {/* ================= NETWORK HOME ================= */}
        <Link to="/network-home" className={isActive("/network-home") ? "active" : ""}>
          ⚡ Network Home
        </Link>

        {/* ================= DT WISE BUILDINGS ================= */}
        <Link to="/dtwise-buildings" className={isActive("/dtwise-buildings") ? "active" : ""}>
          🏢 Dt Wise Buildings
        </Link>

        {/* ================= UPLOAD INPUTS ================= */}
        <div className="menu-item">
          <div
            className="menu-title"
            onClick={() =>
              setOpenMenu(openMenu === "upload" ? "" : "upload")
            }
          >
            📂 Upload Inputs {openMenu === "upload" ? "▾" : "▸"}
          </div>

          {openMenu === "upload" && (
            <div className="submenu-right show">
              <Link
                to="/network-inputs-baseline"
                className="submenu-link"
              >
                📥 Baseline Inputs
              </Link>
            </div>
          )}
        </div>

        {/* ================= OPTIMIZE ================= */}
        <Link to="/optimize" className={isActive("/optimize") ? "active" : ""}>
          ⚙️ Optimize Network
        </Link>

        {/* ================= RESULTS ================= */}
        <div className="menu-item">
          <div
            className="menu-title"
            onClick={() =>
              setOpenMenu(openMenu === "results" ? "" : "results")
            }
          >
            📊 Results {openMenu === "results" ? "▾" : "▸"}
          </div>

          {openMenu === "results" && (
            <div className="submenu-right show">

              <Link to="/real-power-baseline" className="submenu-link">
                🔌 Real Power
              </Link>

              <Link to="/reactive-power-baseline" className="submenu-link">
                🌀 Reactive Power
              </Link>

              {/* VOLTAGE */}
              <div className="menu-item nested">
                <div
                  className="menu-title"
                  onClick={(e) => {
                    e.stopPropagation();
                    setOpenSubMenu(
                      openSubMenu === "voltage" ? "" : "voltage"
                    );
                  }}
                >
                  ⚡ Voltage {openSubMenu === "voltage" ? "▾" : "▸"}
                </div>

                {openSubMenu === "voltage" && (
                  <div className="submenu-right show">
                    <Link to="/megnitude-baseline" className="submenu-link">
                      📈 Magnitude
                    </Link>
                    <Link to="/angle-baseline" className="submenu-link">
                      📐 Angle
                    </Link>
                  </div>
                )}
              </div>

              {/* LINE LOADING */}
              <div className="menu-item nested">
                <div
                  className="menu-title"
                  onClick={(e) => {
                    e.stopPropagation();
                    setOpenSubMenu(
                      openSubMenu === "line" ? "" : "line"
                    );
                  }}
                >
                  📏 Line Loading {openSubMenu === "line" ? "▾" : "▸"}
                </div>

                {openSubMenu === "line" && (
                  <div className="submenu-right show">
                    <Link to="/line-loading-baseline" className="submenu-link">
                      🟢 Normal Lines
                    </Link>
                    <Link to="/overloaded-lines-baseline" className="submenu-link">
                      🔴 Overloaded Lines
                    </Link>
                  </div>
                )}
              </div>

              <Link to="/transformer-loading-baseline" className="submenu-link">
                🔁 Transformer Loading
              </Link>

              <Link to="/network-map-baseline" className="submenu-link">
                🗺️ Network Map
              </Link>

              <Link to="/line-loading-map-baseline" className="submenu-link">
                📍 Line Loading Map
              </Link>

            </div>
          )}
        </div>

      </nav>
    </div>
  );
}

export default NetworkBar;