import React, { useEffect, useMemo } from "react";

const Hvac = ({
  data = [],
  params = {},
  options = {},
  updateParam,
  toggleSelect,
  rowStyle,
}) => {

  const hvacFields = ["hotwater_temp", "cooling_temp"];

  // ================= SAFE ID =================
  const safeId = (id) =>
    id === undefined || id === null ? "" : String(id).trim();

  // ================= UNIQUE BUILDINGS =================
  const uniqueData = useMemo(() => {
    const seen = new Set();

    return (data || []).filter((b) => {
      const id = safeId(b?.name);
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
  }, [data]);

  // ============================================================
  // 🔥 COOLING LOGIC (ROBUST MATCH)
  // ============================================================
  const getCoolingFromUseType = (useType) => {
    const type = (useType || "").toUpperCase().trim();

    if (
      type.includes("HOTEL") ||
      type.includes("HOSPITAL") ||
      type.includes("SCHOOL") ||
      type.includes("RESTAURANT") ||
      type.includes("RETAIL")
    ) {
      return "CENTRAL_AC";
    }

    if (
      type.includes("UNIVERSITY") ||
      type.includes("OFFICE") ||
      type.includes("RES") || 
      type.includes('COMMERCIAL') ||
      type.includes('MIXED')
    ) {
      return "DECENTRALIZED_AC";
    }

    return "NONE";
  };

  // ============================================================
  // 🔥 SET DEFAULT VALUES (FIX NONE ISSUE)
  // ============================================================
  useEffect(() => {
    uniqueData.forEach((b) => {
      const id = safeId(b?.name);

      // HOTWATER DEFAULT
      if (!params?.[id]?.hotwater_temp) {
        const defHW = options?.hotwater_temp?.[0]?.value;
        if (defHW !== undefined) {
          updateParam(id, "hotwater_temp", defHW);
        }
      }

      // COOLING DEFAULT (FIX NONE OVERRIDE)
      const current = params?.[id]?.cooling_temp;
      const expected = getCoolingFromUseType(
        b?.sub_class || b?.use_type
      );

      if (
        current === undefined ||
        current === null ||
        current === "" ||
        current === "NONE"
      ) {
        updateParam(id, "cooling_temp", expected);
      }
    });
  }, [uniqueData, options]);

  return (
    <div className="h-75 overflow-auto">
      <table className="table table-hover table-sm m-0">

        {/* HEADER */}
        <thead className="table-dark sticky-top">
          <tr>
            <th>Building</th>
            {hvacFields.map((k) => (
              <th key={k}>{k}</th>
            ))}
          </tr>
        </thead>

        {/* BODY */}
        <tbody>
          {uniqueData.map((b) => {
            const id = safeId(b?.name);

            return (
              <tr
                key={id}
                onClick={() => toggleSelect(id)}
                style={rowStyle(id)}
              >
                <td><b>{id}</b></td>
                {hvacFields.map((key) => {

                  const expected = getCoolingFromUseType(
                    b?.sub_class || b?.use_type
                  );

                  const value =
                    key === "cooling_temp"
                      ? (
                          params?.[id]?.[key] === "NONE"
                            ? expected   // 🔥 FIX: override NONE
                            : params?.[id]?.[key] ?? expected
                        )
                      : (
                          params?.[id]?.[key] ??
                          options?.[key]?.[0]?.value
                        );

                  return (
                    <td key={`${id}-${key}`}>
                      <select
                        className="form-select form-select-sm"
                        value={value}
                        onChange={(e) => {
                          e.stopPropagation();
                          updateParam(id, key, e.target.value);
                        }}
                      >
                        {(options?.[key] || []).map((o, idx) => (
                          <option key={idx} value={o.value}>
                            {o.label}
                          </option>
                        ))}
                      </select>
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>

      </table>
    </div>
  );
};

export default Hvac;