import React, { useState } from "react";
import axios from "axios";
import { ToastContainer, toast } from "react-toastify";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  ResponsiveContainer,
  Legend,
} from "recharts";

import "react-toastify/dist/ReactToastify.css";

export default function LineLoading() {
  const [data, setData] = useState([]);
  const [line, setLine] = useState("");
  const [lineList, setLineList] = useState([]);
  const [snapshot, setSnapshot] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const [hiddenLines, setHiddenLines] = useState({});
  const [showMax, setShowMax] = useState(false); // ✅ NEW

  // ================= FETCH DATA =================
  const fetchData = async () => {
    setLoading(true);
    setMessage("");
    setData([]);

    try {
      let url = "http://127.0.0.1:8000/network/line-loading-baseline";

      const params = {};
      if (snapshot) params.snapshot = snapshot;

      const res = await axios.get(url, { params });

      if (res.status === 200) {
        const apiData = res.data.data || res.data;

        setData(apiData);

        if (apiData.length > 0) {
          const keys = Object.keys(apiData[0]).filter(
            (k) => k !== "snapshot"
          );
          setLineList(keys);
        }

        toast.success("Data Loaded 🚀");
        setMessage(`Loaded ${apiData.length} records`);
      }
    } catch (error) {
      setMessage("Failed to fetch data ❌");
      toast.error("API Error");
    } finally {
      setLoading(false);
    }
  };

  // ================= COLORS =================
  const getColor = (index) =>
    `hsl(${index * 40}, 70%, 50%)`;

  // ================= CLEAR =================
  const clearChart = () => {
    setHiddenLines({});
    setLine("");
  };

  // ================= LEGEND CLICK =================
  const handleLegendClick = (e) => {
    const key = e.dataKey;
    setHiddenLines((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  // ================= MAX LOADING WITH SNAPSHOT =================
  const getMaxLoading = () => {
    if (!data.length || !lineList.length) return [];

    return lineList.map((l) => {
      let maxVal = -Infinity;
      let maxSnap = "";

      data.forEach((d) => {
        const val = Number(d[l] || 0);

        if (val > maxVal) {
          maxVal = val;
          maxSnap = d.snapshot; // ✅ snapshot included
        }
      });

      return {
        line: l,
        max: maxVal,
        snapshot: maxSnap,
      };
    });
  };

  return (
    <div style={{ background: "#f4f6f9", minHeight: "100vh" }}>
      <div style={{ marginLeft: "150px", padding: "15px" }}>
        <div className="container-fluid">

          {/* HEADER */}
          <div className="mb-4 text-center">
            <h2 className="fw-bold">⚡ Line Loading Dashboard</h2>
            <p className="text-muted">
              Multi-line visualization + snapshot analysis
            </p>
          </div>

          {/* FILTER */}
          <div className="card shadow-lg border-0 rounded-4 p-4 mb-4">
            <div className="row g-3">

              <div className="col-md-5">
                <select
                  className="form-select form-select-lg"
                  value={line}
                  onChange={(e) => setLine(e.target.value)}
                  disabled={lineList.length === 0}
                >
                  <option value="">
                    {lineList.length === 0
                      ? "Fetch data first"
                      : "Show All Lines"}
                  </option>

                  {lineList.map((l, i) => (
                    <option key={i} value={l}>
                      {l}
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-md-5">
                <input
                  type="number"
                  className="form-control form-control-lg"
                  placeholder="Snapshot Index"
                  value={snapshot}
                  onChange={(e) => setSnapshot(e.target.value)}
                />
              </div>

              <div className="col-md-2 d-grid">
                <button
                  className="btn btn-primary btn-lg fw-bold"
                  onClick={fetchData}
                >
                  {loading ? "Loading..." : "Fetch"}
                </button>
              </div>

            </div>
          </div>

          {/* STATUS */}
          <div className="text-center mb-3 text-muted">
            {message || "Fetch data to visualize"}
          </div>

          {/* CHART + TABLE */}
          <div className="row">

            {/* CHART */}
            <div className="col-lg-6">
              <div className="card shadow-lg rounded-4 p-3 h-100">

                {/* HEADER */}
                <div className="d-flex justify-content-between align-items-center mb-3">
                  <h5 className="mb-0">
                    📈 Line Loading Trend {line ? `(${line})` : "(All Lines)"}
                  </h5>

                  <div className="d-flex gap-2">
                  

                    <button
                      className="btn btn-sm btn-outline-danger"
                      onClick={clearChart}
                    >
                      Clear Chart
                    </button>
                  </div>
                </div>

                {/* ================= MAX TABLE ================= */}
                
                {/* ================= CHART ================= */}
                {data.length > 0 ? (
                  <ResponsiveContainer width="100%" height={350}>
                    <LineChart data={data}>
                      <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                      <XAxis dataKey="snapshot" />
                      <YAxis />

                      <Tooltip
                        formatter={(value) =>
                          typeof value === "number"
                            ? value.toFixed(3)
                            : value
                        }
                      />

                      <Legend onClick={handleLegendClick} />

                      {!line &&
                        lineList.map((l, i) => (
                          <Line
                            key={l}
                            dataKey={l}
                            stroke={getColor(i)}
                            strokeWidth={2}
                            dot={false}
                            hide={hiddenLines[l]}
                          />
                        ))}

                      {line && (
                        <Line
                          dataKey={line}
                          stroke="#ff7e5f"
                          strokeWidth={3}
                          dot={false}
                        />
                      )}
                    </LineChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="text-center p-5 text-muted">
                    {loading ? "Loading..." : "No Data"}
                  </div>
                )}

              </div>
            </div>

            {/* TABLE */}
            <div className="col-lg-6">
              <div className="card shadow-lg rounded-4 h-100">

                <div style={{ maxHeight: "400px", overflowY: "auto" }}>
                  {data.length > 0 ? (
                    <table className="table table-hover mb-0">
                      <thead className="table-dark">
                        <tr>
                          {Object.keys(data[0]).map((k) => (
                            <th key={k}>{k}</th>
                          ))}
                        </tr>
                      </thead>

                      <tbody>
                        {data.slice(0, 50).map((row, i) => (
                          <tr key={i}>
                            {Object.values(row).map((v, j) => (
                              <td key={j}>
                                {typeof v === "number"
                                  ? v.toFixed(3)
                                  : v}
                              </td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <div className="text-center p-5 text-muted">
                      No Data
                    </div>
                  )}
                </div>

              </div>
            </div>

          </div>

        </div>
            <div className=" mt-2 d-flex justify-content-end">
                <button
                  className="btn btn-sm btn-outline-primary me-3"
                  onClick={() => setShowMax(!showMax)}
                >
                  {showMax ? "Hide  " : "Show Max Loading"}
                </button>
            </div>
            {showMax && (
  <div className="mt-2 d-flex justify-content-end me-3">
    
    <div
      className="shadow-sm"
      style={{
        maxHeight: "180px",
        overflowY: "auto",
        width: "420px",
        background: "#fff",
        borderRadius: "8px",
      }}
    >
      <table className="table table-sm table-bordered mb-0">
        <thead className="table-dark">
          <tr>
            <th>Line</th>
            <th>Max Loading</th>
            <th>Snapshot</th>
          </tr>
        </thead>

        <tbody>
          {getMaxLoading().map((item, i) => (
            <tr key={i}>
              <td>{item.line}</td>
              <td>{item.max.toFixed(3)}</td>
              <td>{item.snapshot}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>

  </div>
)}
      </div>
       
      <ToastContainer />
    </div>
  );
}