import React, { useEffect, useState, useCallback } from "react";
import { getLocator, saveUseData } from "../../api/api";   // ✅ USE API
import Archetypes from "./Archetypes";
import Assemblies from "./Assemblies";
import Components from "./Components";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../Componants/Sidebar";
import { Link } from "react-router-dom";

function Database() {

  const navigate = useNavigate();

  const [paths, setPaths] = useState({});
  const [activeTab, setActiveTab] = useState("archetypes");
  const [assemblyType, setAssemblyType] = useState("hvac");

  const [archetypeSaveFn, setArchetypeSaveFn] = useState(null);
  const [assembliesSaveFn, setAssembliesSaveFn] = useState(null);
  const [componentsSaveFn, setComponentsSaveFn] = useState(null);

  // ============================
  // LOAD DATABASE PATHS
  // ============================
  useEffect(() => {

    const loadPaths = async () => {
      try {

        // ✅ project_id auto added
        const res = await getLocator();

        setPaths(res.data || {});

      } catch (err) {
        console.error(err);
        toast.error("❌ Upload files first (project not found)");
      }
    };

    loadPaths();

  }, []);

  // ============================
  // SAVE ALL DATA
  // ============================
  const saveAll = useCallback(async () => {

    const archetypes = archetypeSaveFn ? archetypeSaveFn() : {};
    const assemblies = assembliesSaveFn ? assembliesSaveFn() : {};
    const components = componentsSaveFn ? componentsSaveFn() : {};

    const payload = { archetypes, assemblies, components };

    try {

      const res = await saveUseData(payload);   // ✅ CLEAN API

      toast.success(res.data?.status || "✅ All data saved");

    } catch (err) {
      console.error(err);
      toast.error("❌ Save failed");
    }

  }, [archetypeSaveFn, assembliesSaveFn, componentsSaveFn]);

  // ============================
  // REGISTER SAVE FUNCTIONS
  // ============================
  const registerArchetypeSave = (fn) => setArchetypeSaveFn(() => fn);
  const registerAssembliesSave = (fn) => setAssembliesSaveFn(() => fn);
  const registerComponentsSave = (fn) => setComponentsSaveFn(() => fn);

  // ============================
  // UI
  // ============================
  return (

    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "Segoe UI" }}>

      <Sidebar />

      <div
        style={{
          marginLeft: "170px",
          padding: "20px",
          width: "100%",
          background: "#f5f6fa"
        }}
      >

        <ToastContainer position="top-right" autoClose={3000} />

        <h4 style={{ fontWeight: "600", marginBottom: "15px" }}>
          Input Database
        </h4>

        {/* DATABASE SELECT */}
        <label className="form-label">Database</label>
        <br />

        <select
          className="form-select form-select-sm"
          style={{ width: "200px", marginBottom: "10px" }}
          value={paths.database_path || ""}
          readOnly
        >
          <option value={paths.database_path}>India</option>
        </select>

        {/* ================= TABS ================= */}
        <ul className="nav nav-underline mt-3 mb-2">

          <li className="nav-item">
            <button
              className={`nav-link ${activeTab === "archetypes" ? "active" : ""}`}
              onClick={() => setActiveTab("archetypes")}
            >
              Archetypes
            </button>
          </li>

          <li className="nav-item dropdown">
            <button
              className={`nav-link dropdown-toggle ${activeTab === "assemblies" ? "active" : ""}`}
              data-bs-toggle="dropdown"
            >
              Assemblies
            </button>

            <ul className="dropdown-menu">
              {["envelope", "hvac", "supply"].map(type => (
                <li key={type}>
                  <button
                    className="dropdown-item"
                    onClick={(e) => {
                      setActiveTab("assemblies");
                      setAssemblyType(type);

                      const dropdownMenu = e.currentTarget.closest(".dropdown-menu");
                      const dropdown = e.currentTarget.closest(".dropdown");
                      const toggle = dropdown.querySelector(".dropdown-toggle");

                      if (dropdownMenu) dropdownMenu.classList.remove("show");
                      if (toggle) {
                        toggle.classList.remove("show");
                        toggle.setAttribute("aria-expanded", "false");
                      }
                    }}
                  >
                    {type}
                  </button>
                </li>
              ))}
            </ul>
          </li>

          <li className="nav-item">
            <button
              className={`nav-link ${activeTab === "components" ? "active" : ""}`}
              onClick={() => setActiveTab("components")}
            >
              Components
            </button>
          </li>

        </ul>

        {/* ================= CONTENT ================= */}
        <div className="mt-3">

          {activeTab === "archetypes" && (
            <Archetypes paths={paths} registerSave={registerArchetypeSave} />
          )}

          {activeTab === "assemblies" && (
            <Assemblies
              paths={paths}
              type={assemblyType}
              key={assemblyType}
              registerSave={registerAssembliesSave}
            />
          )}

          {activeTab === "components" && (
            <Components
              key={paths.components}
              paths={paths}
              registerSave={registerComponentsSave}
            />
          )}

        </div>

       {/* ================= BUTTONS ================= */}
<div style={{ marginTop: "20px", display: "flex", gap: "10px" }}>

  <button
    onClick={saveAll}
    className="btn btn-success btn-sm d-flex align-items-center gap-1"
  >
    💾 <span>Save All</span>
  </button>

  <Link
    to="/locator"
    className="btn btn-primary btn-sm d-flex align-items-center gap-1"
  >
    🏢 <span>Building Details</span> →
  </Link>

</div>

      </div>
    </div>
  );
}

export default Database;