import React, { useMemo, useEffect, useState } from "react";
import "./Map.css";
import {
  MapContainer,
  TileLayer,
  GeoJSON,
  useMap,
} from "react-leaflet";
import L from "leaflet";
import {
  FaMap,
  FaGlobe,
  FaHospital,
  FaSchool,
  FaBuilding,
} from "react-icons/fa";

// 📌 MAP CONTROL
const MapController = ({ geoJson, activeBuilding }) => {
  const map = useMap();

  useEffect(() => {
    if (!geoJson?.features?.length) return;
    const layer = L.geoJSON(geoJson);
    map.fitBounds(layer.getBounds(), { padding: [40, 40] });
  }, [geoJson, map]);

  useEffect(() => {
    if (!activeBuilding?.geometry) return;
    const layer = L.geoJSON(activeBuilding.geometry);
    map.flyToBounds(layer.getBounds(), {
      padding: [80, 80],
      duration: 1,
    });
  }, [activeBuilding, map]);

  return null;
};

const MapAll = ({ allData, selected, toggleSelect, searchText }) => {
  const [activeBuilding, setActiveBuilding] = useState(null);
  const [mapMode, setMapMode] = useState("street");
  const [activeFilter, setActiveFilter] = useState(null);

  const [showLegend, setShowLegend] = useState(false);
  const [showMode, setShowMode] = useState(false);

  // ✅ GEOJSON
  const geoJson = useMemo(() => {
    return {
      type: "FeatureCollection",
      features: (allData.zone || []).map((b) => ({
        type: "Feature",
        geometry: b.geometry,
        properties: b,
      })),
    };
  }, [allData]);

  // ✅ DYNAMIC SUBCLASSES
  const dynamicSubclasses = useMemo(() => {
    const set = new Set();
    (allData.zone || []).forEach((b) => {
      if (b.sub_class) {
        set.add(b.sub_class.toUpperCase());
      }
    });
    return Array.from(set);
  }, [allData]);

  // 🎨 COLOR GENERATOR
  const generateColor = (index) => {
    const colors = [
      "#f44336", "#e91e63", "#9c27b0", "#673ab7",
      "#3f51b5", "#2196f3", "#03a9f4", "#00bcd4",
      "#009688", "#4caf50", "#8bc34a", "#cddc39",
      "#ffeb3b", "#ffc107", "#ff9800", "#ff5722",
      "#795548", "#607d8b"
    ];
    return colors[index % colors.length];
  };

  // ✅ DYNAMIC COLOR MAP
  const SUBCLASS_COLORS = useMemo(() => {
    const obj = {};
    dynamicSubclasses.forEach((sub, i) => {
      obj[sub] = generateColor(i);
    });
    return obj;
  }, [dynamicSubclasses]);

  // 🎨 GET COLOR
  const getColor = (subClass) =>
    SUBCLASS_COLORS[(subClass || "").toUpperCase()] || "#9E9E9E";

  // FILTER + SEARCH
  const filteredData = useMemo(() => {
    let features = geoJson.features;

    if (activeFilter) {
      features = features.filter(
        (f) => f.properties.sub_class?.toUpperCase() === activeFilter
      );
    }

    if (searchText?.trim()) {
      features = features.filter((f) =>
        f.properties.name
          ?.toLowerCase()
          .includes(searchText.toLowerCase())
      );
    }

    return { ...geoJson, features };
  }, [geoJson, activeFilter, searchText]);

  // STYLE
  const style = (feature) => {
    const p = feature.properties;
    const isSelected = selected.includes(p.name);
    const color = getColor(p.sub_class);

    return {
      color: isSelected ? "#000" : color,
      weight: isSelected ? 8 : 2,
      fillColor: color,
      fillOpacity: isSelected ? 1 : 0.7,
    };
  };

  // ICON LOGIC
  const getIcon = (key) => {
    if (key.includes("HOSPITAL")) return <FaHospital />;
    if (key.includes("SCHOOL")) return <FaSchool />;
    return <FaBuilding />;
  };

  // EVENTS
  const onEachFeature = (feature, layer) => {
    const p = feature.properties;

    layer.on({
      click: () => {
        toggleSelect(p.name);
        setActiveBuilding(p);
      },
    });

    layer.bindTooltip(
      `<b>${p.name}</b><br/>${p.sub_class}`,
      { sticky: true }
    );

    layer.bindPopup(`
      <div>
        <h5>${p.name}</h5>
        <b>Class:</b> ${p.class || "-"}<br/>
        <b>Sub Class:</b> ${p.sub_class || "-"}<br/>
        <b>Height:</b> ${p.height || "-"} m<br/>
        <b>Volume:</b> ${p.volume || "-"} m³<br/>
        <b>Footprint:</b> ${p.footprint_area || "-"} m²
      </div>
    `);
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      
      {/* MAP */}
      <div style={{ flex: 1, position: "relative" }}>
        
        <MapContainer
          center={[20.5937, 78.9629]}
          zoom={16}
          style={{ height: "100%", width: "100%" }}
        >
          {mapMode === "street" && (
            <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          )}

          {mapMode === "satellite" && (
            <TileLayer url="https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png" />
          )}

          {/* 🔥 FIXED HERE */}
          <GeoJSON
            key={activeFilter || "all"}   // ✅ FORCE RE-RENDER
            data={filteredData}
            style={style}
            onEachFeature={onEachFeature}
          />

          <MapController
            geoJson={filteredData}
            activeBuilding={activeBuilding}
          />
        </MapContainer>

        {/* 🔘 BUTTONS */}
        <div className="map-controls">
          <button onClick={() => setShowMode(!showMode)}>
            <FaMap />
          </button>

          <button onClick={() => setShowLegend(!showLegend)}>
            🏢
          </button>
        </div>

        {/* 🌍 MODE */}
        {showMode && (
          <div className="map-mode">
            <button
              className={mapMode === "street" ? "active" : ""}
              onClick={() => setMapMode("street")}
            >
              <FaMap /> Street
            </button>

            <button
              className={mapMode === "satellite" ? "active" : ""}
              onClick={() => setMapMode("satellite")}
            >
              <FaGlobe /> Satellite
            </button>
          </div>
        )}

        {/* 🎨 LEGEND */}
        {showLegend && (
          <div className="map-legend">
            <h6>🏢 Building Types</h6>

            {Object.entries(SUBCLASS_COLORS).map(([key, color]) => (
              <div
                key={key}
                onClick={() =>
                  setActiveFilter(activeFilter === key ? null : key)
                }
                className={`legend-item ${
                  activeFilter === key ? "active" : ""
                }`}
              >
                <span style={{ background: color }} />

                {getIcon(key)}

                <label>{key}</label>
              </div>
            ))}

            <button
              className="legend-reset"
              onClick={() => setActiveFilter(null)}
            >
              Reset Filter
            </button>
          </div>
        )}

      </div>
    </div>
  );
};

export default MapAll;