import React, { useEffect, useState, useCallback } from "react";
import { toast } from "react-toastify";
import { getUseData } from "../../api/api";

function Archetypes({ paths, registerSave }) {

  const [useTypes, setUseTypes] = useState([]);
  const [selectedUse, setSelectedUse] = useState("");

  const [rowData, setRowData] = useState({});
  const [scheduleData, setScheduleData] = useState({ columns: [], rows: [] });

  const [multipliers, setMultipliers] = useState({
    HW: {},
    AC: {},
    AUX: {},
    EaEl: {},
  });

  // ✅ ONLY USED FOR MIXED
  const [mixedDistribution, setMixedDistribution] = useState({
    COMMERCIAL: 0.5,
    RESIDENTIAL: 0.5,
  });

  const [activeMultiplierTab, setActiveMultiplierTab] = useState("HW");
  const [activeScheduleTab, setActiveScheduleTab] = useState("occupancy");

  const tabs = [
    "occupancy","appliances","lighting","hot_water",
    "heating","cooling","AC_Usage","processes",
    "servers","electromobility",
  ];

  const multiplierTabs = ["HW", "AUX", "AC", "EaEl"];

  useEffect(() => {
    if (paths.use_types?.length > 0) {
      setUseTypes(paths.use_types);

      if (!selectedUse) {
        const firstUse = paths.use_types[0];
        setSelectedUse(firstUse);
        loadUseRow(firstUse);
      }
    }
  }, [paths]);

  // ✅ SAVE FUNCTION (ONLY MIXED CHANGED)
  const saveFn = useCallback(() => {

    const payload = {
      use_type: selectedUse,
      row_data: rowData || {},
      multipliers: multipliers || {},
      schedule_rows: scheduleData?.rows || [],
    };

    // ✅ ONLY APPLY FOR MIXED
    if (selectedUse === "MIXED") {

      const per_commercial = parseFloat(mixedDistribution.COMMERCIAL) || 0;
      const per_residential = parseFloat(mixedDistribution.RESIDENTIAL) || 0;

      const total = per_commercial + per_residential;

      if (Math.abs(total - 1) > 0.0001) {
        toast.error("❌ commercial and residential must equal 1");
        return null;
      }

      payload.per_commercial= per_commercial;
      payload.per_residential = per_residential;
    }

    return payload;

  }, [selectedUse, rowData, multipliers, scheduleData, mixedDistribution]);

  useEffect(() => {
    if (registerSave) registerSave(saveFn);
  }, [registerSave, saveFn]);

  const loadUseRow = async (use) => {
    if (!use) return;

    try {
      setSelectedUse(use);

      const res = await getUseData(use);

      if (res.data.error) {
        toast.error(res.data.error);

        setRowData({});
        setScheduleData({ columns: [], rows: [] });
        setMultipliers({ HW: {}, AC: {}, AUX: {}, EaEl: {} });
        return;
      }

      setRowData(res.data.use_row || {});
      setScheduleData(res.data.schedule || { columns: [], rows: [] });

      setMultipliers({
        HW: res.data.mul_HW_row || {},
        AC: res.data.mul_AC_row || {},
        AUX: res.data.mul_AUX_row || {},
        EaEl: res.data.mul_EaEl_row || {},
      });

    } catch (err) {
      console.error(err);
      toast.error("❌ Failed to load data");
    }
  };

  const updateField = (key, value) =>
    setRowData(prev => ({ ...prev, [key]: value }));

  const updateMultiplier = (tab, key, value) =>
    setMultipliers(prev => ({
      ...prev,
      [tab]: { ...prev[tab], [key]: value },
    }));

  const updateScheduleCell = (rowIndex, col, value) => {
    const newRows = [...scheduleData.rows];
    newRows[rowIndex][col] = value;
    setScheduleData(prev => ({ ...prev, rows: newRows }));
  };

  return (
    <div style={{ width: "80%", padding: "10px 5px" }}>

      {/* HEADER */}
      <div className="card shadow-sm mb-3">
        <div className="card-body p-1">

          <h6 style={{ fontWeight: "600" }}>Archetypes Database</h6>

          <input
            value={paths.archetypes || ""}
            readOnly
            className="form-control form-control-sm mb-2"
          />

          <label className="form-label">Use Type</label>

          <select
            className="form-select form-select-sm"
            style={{ maxWidth: "250px" }}
            value={selectedUse}
            onChange={(e) => loadUseRow(e.target.value)}
          >
            {useTypes.map((u, i) => (
              <option key={i} value={u}>
                {u}
              </option>
            ))}
          </select>

        </div>
      </div>

      {/* ✅ ONLY SHOW FOR MIXED */}
      {selectedUse === "MIXED" && (
        <div className="card shadow-sm mb-3">
          <div className="card-body p-2">

            <h6>Mixed Distribution (0–1)</h6>

            <div className="mb-2">
              <label>COMMERCIAL</label>
              <input
                type="number"
                step="0.01"
                value={mixedDistribution.COMMERCIAL}
                onChange={(e) =>
                  setMixedDistribution(prev => ({
                    ...prev,
                    COMMERCIAL: parseFloat(e.target.value) || 0
                  }))
                }
                className="form-control form-control-sm"
              />
            </div>

            <div className="mb-2">
              <label>RESIDENTIAL</label>
              <input
                type="number"
                step="0.01"
                value={mixedDistribution.RESIDENTIAL}
                onChange={(e) =>
                  setMixedDistribution(prev => ({
                    ...prev,
                    RESIDENTIAL: parseFloat(e.target.value) || 0
                  }))
                }
                className="form-control form-control-sm"
              />
            </div>

            <small>
              Total: {(mixedDistribution.COMMERCIAL + mixedDistribution.RESIDENTIAL).toFixed(2)}
            </small>

          </div>
        </div>
      )}

      {/* DATA TABLE */}
      {selectedUse && Object.keys(rowData).length > 0 && (
        <div className="card shadow-sm mb-3">
          <div className="card-body p-1">

            <h6>{selectedUse} Properties</h6>

            <div className="table-responsive">
              <table className="table table-bordered table-sm text-center">
                <thead className="table-light">
                  <tr>
                    {Object.keys(rowData).map(key => (
                      <th key={key}>{key}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    {Object.keys(rowData).map(key => (
                      <td key={key}>
                        <input
                          value={rowData[key] || 0}
                          onChange={(e) => updateField(key, e.target.value)}
                          className="form-control form-control-sm text-center"
                        />
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </div>

          </div>
        </div>
      )}

      {/* MULTIPLIERS */}
      {selectedUse && (
        <ul className="nav nav-pills mb-2">
          {multiplierTabs.map(tab => (
            <li key={tab}>
              <button
                className={`nav-link btn-sm ${activeMultiplierTab === tab ? "active" : ""}`}
                onClick={() => setActiveMultiplierTab(tab)}
              >
                {tab}
              </button>
            </li>
          ))}
        </ul>
      )}

      {/* MULTIPLIER TABLE */}
      {Object.keys(multipliers[activeMultiplierTab] || {}).length > 0 && (
        <div className="card shadow-sm mb-3">
          <div className="card-body p-1">

            <h6>{activeMultiplierTab} Multipliers</h6>

            <table className="table table-bordered table-sm text-center">
              <thead className="table-light">
                <tr>
                  {Object.keys(multipliers[activeMultiplierTab]).map(key => (
                    <th key={key}>{key}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  {Object.keys(multipliers[activeMultiplierTab]).map(key => (
                    <td key={key}>
                      <input
                        value={multipliers[activeMultiplierTab][key] || 0}
                        onChange={(e) =>
                          updateMultiplier(activeMultiplierTab, key, e.target.value)
                        }
                        className="form-control form-control-sm text-center"
                      />
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>

          </div>
        </div>
      )}

      {/* SCHEDULE */}
      {scheduleData.rows.length > 0 && (
        <div className="card shadow-sm">
          <div className="card-body p-1">

            <h6>Schedule</h6>

            <ul className="nav nav-underline mb-2">
              {tabs.map(tab => (
                <li key={tab}>
                  <button
                    className={`nav-link btn-sm ${activeScheduleTab === tab ? "active" : ""}`}
                    onClick={() => setActiveScheduleTab(tab)}
                  >
                    {tab}
                  </button>
                </li>
              ))}
            </ul>

            <div className="table-responsive">
              <table className="table table-bordered table-sm text-center">
                <thead className="table-light">
                  <tr>
                    <th>Day</th>
                    {Array.from({ length: 24 }, (_, h) => (
                      <th key={h}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {["Weekday", "Saturday", "Sunday"].map((day, dayIndex) => (
                    <tr key={day}>
                      <td>{day}</td>
                      {Array.from({ length: 24 }, (_, h) => {
                        const rowIndex = h + dayIndex * 24;
                        return (
                          <td key={h}>
                            <input
                              value={scheduleData.rows[rowIndex]?.[activeScheduleTab] || 0}
                              onChange={(e) =>
                                updateScheduleCell(rowIndex, activeScheduleTab, e.target.value)
                              }
                              className="form-control form-control-sm text-center"
                            />
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

          </div>
        </div>
      )}

    </div>
  );
}

export default Archetypes;