import React, { useMemo } from "react";

const Zone = ({
  data = [],
  params = {},
  updateParam,
  toggleSelect,
  rowStyle,
}) => {

  const columns = [
    "class",
    "sub_class",
    "footprint_area",
    "floor_area",
    "height",
    "volume_m3",
    "wall_area",
    "roof_area",
    "window_area",
    "use_type",
    "lat",        // ✅ FIXED
    "lon"         // ✅ FIXED (or use "long" if backend uses that)
  ];

  // ================= SAFE ID =================
  const safeId = (id) =>
    id === undefined || id === null ? "" : String(id).trim();

  // ================= UNIQUE DATA =================
  const uniqueData = useMemo(() => {
    const seen = new Set();

    return (data || []).filter((b) => {
      const id = safeId(b?.name);
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
  }, [data]);

  if (!uniqueData.length) {
    return <p>Loading ...</p>;
  }

  return (
    <div className="h-75 overflow-auto">
      <table className="table table-hover table-sm m-0">

        {/* HEADER */}
        <thead className="table-dark sticky-top">
          <tr>
            <th>Building</th>
            {columns.map((c) => (
              <th key={c}>{c}</th>
            ))}
          </tr>
        </thead>

        {/* BODY */}
        <tbody>
          {uniqueData.map((b) => {
            const id = safeId(b?.name);

            return (
              <tr
                key={id}
                onClick={() => toggleSelect(id)}
                style={rowStyle(id)}
              >
                <td><b>{id}</b></td>

                {columns.map((key) => {
                  const value =
                    params?.[id]?.[key] ?? b?.[key] ?? "";

                  return (
                    <td key={`${id}-${key}`}>
                      <input
                        className="form-control form-control-sm"
                        value={value}

                        onClick={(e) => e.stopPropagation()}

                        onChange={(e) => {
                          let val = e.target.value;

                          // 🔥 Convert numeric fields
                          if (
                            [
                              "footprint_area",
                              "floor_area",
                              "height",
                              "volume_m3",
                              "wall_area",
                              "roof_area",
                              "window_area",
                              "lat",      // ✅ include lat
                              "lon"       // ✅ include lon
                            ].includes(key)
                          ) {
                            val = val === "" ? "" : Number(val);
                          }

                          updateParam(id, key, val);
                        }}
                      />
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>

      </table>
    </div>
  );
};

export default Zone;