import React, { useState, useEffect } from "react";
import Sidebar from "../../Componants/Sidebar";
import "./Dashboard.css";
import { Link } from "react-router-dom";
import { getWeatherFile, getBuildingShape } from "../../api/api";

function Dashboard() {

  const [message, setMessage] = useState("");

  const [loadingBuilding, setLoadingBuilding] = useState(false);
  const [loadingWeather, setLoadingWeather] = useState(false);

  const [buildingLoaded, setBuildingLoaded] = useState(false);
  const [weatherLoaded, setWeatherLoaded] = useState(false);

  const [buildingFiles, setBuildingFiles] = useState([]);
  const [weatherFiles, setWeatherFiles] = useState([]);

  const [projectId, setProjectId] = useState(null);

  // ==========================
  // 🔄 LOAD FROM LOCAL STORAGE
  // ==========================
  useEffect(() => {
    const pid = localStorage.getItem("project_id");
    const bFiles = JSON.parse(localStorage.getItem("building_files") || "[]");
    const wFiles = JSON.parse(localStorage.getItem("weather_files") || "[]");

    if (pid) setProjectId(pid);

    if (bFiles.length > 0) {
      setBuildingFiles(bFiles);
      setBuildingLoaded(true);
    }

    if (wFiles.length > 0) {
      setWeatherFiles(wFiles);
      setWeatherLoaded(true);
    }
  }, []);

  // ==========================
  // 📁 COMMON FILE NAME EXTRACTOR
  // ==========================
  const extractFileName = (path) => {
    if (!path) return "";
    return path.split(/[/\\]/).pop(); // handles both / and \
  };

  // ==========================
  // 🏢 BUILDING LOAD
  // ==========================
  const handleLoadBuilding = async () => {
    setMessage("");

    try {
      setLoadingBuilding(true);

      const res = await getBuildingShape();
      const data = res.data;

      const pid = data.project_id;
      setProjectId(pid);
      localStorage.setItem("project_id", pid);

      let files = [];

      // ✅ CASE 1: backend sends multiple shapefile parts
      if (Array.isArray(data.building_files)) {
        files = data.building_files.map(f => extractFileName(f));
      }
      // ✅ CASE 2: single shapefile path
      else if (data.building_path) {
        const fileName = extractFileName(data.building_path);

        // show all related shapefile parts (optional)
        const baseName = fileName.replace(".shp", "");

        files = [
          `${baseName}.shp`,
          `${baseName}.dbf`,
          `${baseName}.shx`,
          `${baseName}.prj`
        ];
      }

      setBuildingFiles(files);
      setBuildingLoaded(true);

      localStorage.setItem("building_files", JSON.stringify(files));

      setMessage(data.message || "🏢 Building loaded ✔");

    } catch (err) {
      setMessage(err.response?.data?.error || "Building load failed ❌");
    } finally {
      setLoadingBuilding(false);
    }
  };

  // ==========================
  // 🌦 WEATHER LOAD
  // ==========================
  const handleLoadWeather = async () => {
    setMessage("");

    try {
      setLoadingWeather(true);

      const project_id = localStorage.getItem("project_id");

      if (!project_id) {
        setMessage("⚠ Load building first");
        return;
      }

      const res = await getWeatherFile(project_id);
      const data = res.data;

      let files = [];

      // ✅ CASE 1: multiple weather files
      if (Array.isArray(data.weather_files)) {
        files = data.weather_files.map(f => extractFileName(f));
      }
      // ✅ CASE 2: single EPW file
      else if (data.weather_path) {
        const fileName = extractFileName(data.weather_path);
        files = [fileName];
      }

      setWeatherFiles(files);
      setWeatherLoaded(true);

      localStorage.setItem("weather_files", JSON.stringify(files));

      setMessage(data.message || "🌦 Weather loaded ✔");

    } catch (err) {
      setMessage(err.response?.data?.error || "Weather load failed ❌");
    } finally {
      setLoadingWeather(false);
    }
  };

  // ==========================
  // 🔄 RESET
  // ==========================
  const handleReset = () => {
    if (!window.confirm("Reset all data?")) return;

    setBuildingLoaded(false);
    setWeatherLoaded(false);
    setBuildingFiles([]);
    setWeatherFiles([]);
    setProjectId(null);
    setMessage("");

    localStorage.removeItem("project_id");
    localStorage.removeItem("building_files");
    localStorage.removeItem("weather_files");
  };

  return (
    <div className="container-fluid dashboard-dark-bg">
      <div className="row">

        {/* SIDEBAR */}
        <div className="col-lg-1 p-0 sidebar-wrapper me-4">
          <Sidebar />
        </div>

        {/* MAIN */}
        <div className="col-lg-10 main-wrapper ms-4">

          <div className="page-header mb-4 mt-5">
            <h2 className="text-center fw-bold ">
              📊 Upload Demand Input files 
            </h2>
           
          </div>

          <div className="row g-3 mt-5">

            {/* BUILDING */}
            <div className="col-lg-6">
              <div className="card-modern-dark h-100">

                <h5>🏢 Building Shapefile</h5>

                {!buildingLoaded ? (
                  <p className="text-muted">Click to load .shp dataset</p>
                ) : (
                  <div>
                    <p className="text-success">✔ Files:</p>

                    {buildingFiles.map((f, i) => (
                      <div key={i} >
                         {f}
                      </div>
                    ))}
                  </div>
                )}

                <button
                  onClick={handleLoadBuilding}
                  disabled={loadingBuilding}
                  className="btn btn-primary mt-3"
                >
                  {loadingBuilding ? "Loading..." : "Upload shapefile"}
                </button>

              </div>
            </div>

            {/* WEATHER */}
            <div className="col-lg-6">
              <div className="card-modern-dark h-100">

                <h5>🌦 Weather File</h5>

                {!weatherLoaded ? (
                  <p className="text-muted">Click to load .epw dataset</p>
                ) : (
                  <div>
                    <p className="text-success mb-5">✔ Files:</p>

                    {weatherFiles.map((f, i) => (
                      <div key={i} className="file-pill-modern mb-2">
                        📄 {f}
                      </div>
                    ))}
                  </div>
                )}

                <button
                  onClick={handleLoadWeather}
                  disabled={loadingWeather}
                  className="btn btn-success mt-3"
                >
                  {loadingWeather ? "Loading..." : "Upload Weather"}
                </button>

              </div>
            </div>

          </div>

          {/* ACTION */}
          <div className="text-center mt-4">

            {buildingLoaded && weatherLoaded ? (
              <div>

                <button className="btn btn-success mb-2" disabled>
                  ✅ All Files Loaded
                </button>

                <br />

                <button
                  onClick={handleReset}
                  className="btn btn-outline-danger me-2"
                >
                  🔄 Reset
                </button>

                <Link to="/map-allbuilding" className="btn btn-primary">
                  🌍 Show Map
                </Link>

              </div>
            ) : (
              <p className="text-muted">
                Load building and weather datasets
              </p>
            )}

          </div>

          {/* MESSAGE */}
          {message && (
            <div className="message-box mt-3 text-center">
              {message}
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

export default Dashboard;