import React, { useEffect, useState, useMemo } from "react";
import {
  MapContainer,
  TileLayer,
  GeoJSON,
  useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

import {
  FaMap,
  FaSatellite,
  FaMoon,
  FaBuilding,
} from "react-icons/fa";

// ================= ROUND =================
const round = (num, d = 2) =>
  num === undefined || num === null || isNaN(num)
    ? "-"
    : Number(num).toFixed(d);

// ================= SAFE NAME =================
const getName = (p) => (p?.name || "Unknown").toString().trim();

// ================= COLOR =================
const getColorBySubClass = () => "#2196F3";

// ================= SAFE FIT BOUNDS =================
const FitBounds = ({ geoJson }) => {
  const map = useMap();

  useEffect(() => {
    if (!map) return;
    if (!geoJson?.features?.length) return;

    const L = require("leaflet");

    try {
      const layer = L.geoJSON(geoJson);
      const bounds = layer.getBounds();

      if (!bounds || !bounds.isValid()) return;

      map.fitBounds(bounds, {
        padding: [20, 20],
        maxZoom: 20,
      });
    } catch (e) {
      console.log("FitBounds crash prevented", e);
    }
  }, [geoJson, map]);

  return null;
};

// ================= SAFE ZOOM =================
const ZoomController = ({ target }) => {
  const map = useMap();

  useEffect(() => {
    if (!map) return;

    const lat = Number(target?.lat);
    const lon = Number(target?.lon);

    if (isNaN(lat) || isNaN(lon)) return;

    try {
      map.setView([lat, lon], 20, { animate: true });
    } catch (e) {
      console.log("Zoom crash prevented");
    }
  }, [target, map]);

  return null;
};

const MapView = ({
  allData,
  selected,
  toggleSelect,
  searchText,
   params,
   mapMode
}) => {
  const zoneData = allData.zone || [];

  const [mapType, setMapType] = useState("normal");
  const [focus, setFocus] = useState(null);

  // ================= SAFE GEOJSON =================
  const geoJson = {
    type: "FeatureCollection",
    features: zoneData
      .filter((b) => {
        if (!b?.geometry) return false;

        const coords = b.geometry?.coordinates;

        return (
          Array.isArray(coords) &&
          coords.length > 0 &&
          !JSON.stringify(coords).includes("null")
        );
      })
      .map((b) => ({
        type: "Feature",
        geometry: b.geometry,
        properties: b,
      })),
  };

  // ================= SEARCH =================
  const searchFiltered = {
    type: "FeatureCollection",
    features: geoJson.features.filter((f) =>
      getName(f.properties)
        .toLowerCase()
        .includes((searchText || "").toLowerCase())
    ),
  };

  // ================= AUTO ZOOM =================
  useEffect(() => {
    if (!searchText) return;

    const match = zoneData.find((b) =>
      (b?.name || "")
        .toLowerCase()
        .includes(searchText.toLowerCase())
    );

    if (match?.lat && match?.lon) {
      setFocus(match);
    }
  }, [searchText, zoneData]);

  // ================= TILE =================
  const getTile = () => {
    switch (mapType) {
      case "satellite":
        return "https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png";
      case "dark":
        return "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png";
      default:
        return "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";
    }
  };

  // ================= STYLE =================
  const styleFeature = (feature) => {
    const p = feature?.properties || {};
    const id = getName(p);

    const baseColor = getColorBySubClass();

    const isSelected = selected?.includes(id);
    const isSearch =
      searchText &&
      id.toLowerCase().includes(searchText.toLowerCase());

    return {
      color: isSelected ? "#ff0000" : baseColor,
      weight: isSearch ? 6 : isSelected ? 4 : 3,
      fillColor: baseColor,
      fillOpacity: isSearch ? 0.95 : isSelected ? 0.8 : 0.6,
    };
  };

  // ================= POPUP + TOOLTIP =================
  const popupHTML = (p) => `
    <div style="font-family:Arial;font-size:12px;min-width:220px">
      <h6>🏢 ${getName(p)}</h6>
      <b>Class:</b> ${p?.class || "-"}<br/>
      <b>Sub Class:</b> ${p?.sub_class || "-"}<br/>
      <b>Area:</b> ${round(p?.floor_area)} m²<br/>
      <b>Height:</b> ${round(p?.height)} m<br/>
    </div>
  `;

  const onEachFeature = (feature, layer) => {
    const p = feature?.properties || {};
    const id = getName(p);

    if (!id) return;

    // ✅ Tooltip (always visible on hover)
    layer.bindTooltip(
      `<b>${id}</b>`,
      {
        sticky: true,
        direction: "top",
      }
    );

    // ✅ Popup (on click)
    layer.bindPopup(popupHTML(p));

    layer.on({
      click: () => {
        toggleSelect(id);
        setFocus(p);
      },
      mouseover: (e) => {
        e.target.setStyle({ weight: 6, fillOpacity: 0.9 });
      },
      mouseout: (e) => {
        e.target.setStyle(styleFeature(feature));
      },
    });
  };

  // ================= LEGEND =================
  const legendItems = useMemo(() => {
    const unique = {};
    zoneData.forEach((b) => {
      if (b.sub_class) {
        unique[b.sub_class] = getColorBySubClass();
      }
    });
    return Object.entries(unique);
  }, [zoneData]);

  const getModeIcon = () => {
    switch (mapType) {
      case "satellite":
        return <FaSatellite />;
      case "dark":
        return <FaMoon />;
      default:
        return <FaMap />;
    }
  };

  return (
    <div style={{ height: "100%", width: "100%", position: "relative" }}>

      {/* CONTROLS */}
      <div style={{
        position: "absolute",
        zIndex: 999,
        top: 10,
        right: 10,
        background: "white",
        padding: "10px",
        borderRadius: "10px"
      }}>
        {getModeIcon()}
        <select
          value={mapType}
          onChange={(e) => setMapType(e.target.value)}
        >
          <option value="normal">Normal</option>
          <option value="satellite">Satellite</option>
          <option value="dark">Dark</option>
        </select>
      </div>

      {/* MAP */}
      <MapContainer
        center={[28.61, 77.2]}
        zoom={18}
        style={{ height: "100%" }}
      >
        <TileLayer url={getTile()} />

        {!searchText && <FitBounds geoJson={geoJson} />}
        {searchText && searchFiltered.features.length > 0 && (
          <FitBounds geoJson={searchFiltered} />
        )}

        {focus && <ZoomController target={focus} />}

        {/* ✅ SAFE RENDER */}
        {geoJson.features.length > 0 && (
          <GeoJSON
            data={geoJson}
            style={styleFeature}
            onEachFeature={onEachFeature}
          />
        )}
      </MapContainer>
    </div>
  );
};

export default MapView;